/* HSK 4 grammar checklist — the grammar points covered at HSK 2.0 level 4.
   Explanations, examples and practice questions are original content written for this app. */
window.CB_GRAMMAR = [
  {"id":"g01","title":{"zh":"把字句","vi":"Câu chữ 把","en":"The 把 construction"},"pattern":"S + 把 + O + V + other element (了 / complement / 到 / 给...)","explain":{"vi":"Dùng 把 để nhấn mạnh việc xử lý một đối tượng xác định và kết quả của hành động. Bẫy thường gặp: động từ không được đứng một mình, phía sau phải có thành phần khác (了, bổ ngữ, 到/给…); phủ định 没/不 và 别 đặt trước 把.","en":"Use 把 to stress what is done to a specific object and its result. Common trap: the verb cannot stand alone and needs something after it (了, a complement, 到/给…); negatives like 没/不/别 go before 把."},"examples":[{"zh":"请把这份合同发给人事部。","py":"Qǐng bǎ zhè fèn hétong fā gěi rénshìbù.","vi":"Vui lòng gửi bản hợp đồng này cho phòng nhân sự.","en":"Please send this contract to the HR department."},{"zh":"我已经把新员工的材料整理好了。","py":"Wǒ yǐjīng bǎ xīn yuángōng de cáiliào zhěnglǐ hǎo le.","vi":"Tôi đã sắp xếp xong tài liệu của nhân viên mới.","en":"I have already sorted out the new employees' documents."}],"quiz":[{"q":"他____那封邮件删了。","options":["被","对","把","向"],"answer":2,"explain":{"vi":"Chủ ngữ 他 là người thực hiện hành động xóa email, nên dùng 把.","en":"He is the one deleting the email, so 把 is needed."}},{"q":"下面哪个句子是正确的？","options":["我把报告写完了。","我把报告写。","我写完把报告了。","我报告把写完了。"],"answer":0,"explain":{"vi":"Sau động từ trong câu 把 phải có thành phần khác (完了), và 把 đứng trước tân ngữ.","en":"The verb needs an extra element (完了) and 把 comes before the object."}},{"q":"你____把会议室的门关上。","options":["了","着","过","别"],"answer":3,"explain":{"vi":"Từ phủ định 别 phải đứng trước 把.","en":"The negative 别 must come before 把."}},{"q":"下面哪个句子是正确的？","options":["他把文件没带来。","他没把文件带来。","他把没文件带来。","他把文件带来没。"],"answer":1,"explain":{"vi":"没 đặt trước 把, không đặt sau tân ngữ.","en":"没 goes before 把, not after the object."}},{"q":"请把这些表格____经理的办公室。","options":["送","送着","送到","送过"],"answer":2,"explain":{"vi":"Cần bổ ngữ 到 + nơi chốn để chỉ kết quả của hành động.","en":"A result element 到 + place is required after the verb."}}]},
  {"id":"g02","title":{"zh":"被字句","vi":"Câu bị động với 被","en":"The 被 passive"},"pattern":"S (receiver) + 被/叫/让 + (agent) + V + other element","explain":{"vi":"Dùng khi chủ ngữ là người/vật chịu tác động, thường mang nghĩa không mong muốn. 被 có thể lược tác nhân, nhưng 叫/让 bắt buộc phải có tác nhân; động từ cũng cần thành phần khác phía sau, và 没/不 đặt trước 被.","en":"Use it when the subject receives the action, often something unwanted. 被 can drop the agent but 叫/让 must have one; the verb still needs something after it, and 没/不 go before 被."},"examples":[{"zh":"我的申请被经理拒绝了。","py":"Wǒ de shēnqǐng bèi jīnglǐ jùjué le.","vi":"Đơn xin của tôi bị quản lý từ chối rồi.","en":"My application was rejected by the manager."},{"zh":"那份材料叫小王拿走了。","py":"Nà fèn cáiliào jiào Xiǎo Wáng ná zǒu le.","vi":"Tài liệu đó bị Tiểu Vương lấy đi rồi.","en":"That document was taken away by Xiao Wang."}],"quiz":[{"q":"我的电脑____同事借走了。","options":["把","被","对","跟"],"answer":1,"explain":{"vi":"Chủ ngữ 电脑 là vật chịu tác động nên dùng 被.","en":"The computer receives the action, so the passive 被 is used."}},{"q":"下面哪个句子是正确的？","options":["这个问题被解决他们了。","这个问题让解决了。","这个问题被没解决。","这个问题被他们解决了。"],"answer":3,"explain":{"vi":"Tác nhân đứng ngay sau 被; 让 phải có tác nhân; 没 đứng trước 被.","en":"The agent follows 被; 让 needs an agent; 没 goes before 被."}},{"q":"那份材料____被人拿走。","options":["没","了","着","过"],"answer":0,"explain":{"vi":"Phủ định 没 đứng trước 被.","en":"The negative 没 goes before 被."}},{"q":"蛋糕叫____吃完了。","options":["了","被","孩子们","把"],"answer":2,"explain":{"vi":"Sau 叫 bắt buộc phải có tác nhân (孩子们).","en":"叫 must be followed by an agent (孩子们)."}},{"q":"他的建议____大家接受了。","options":["被","对","向","从"],"answer":0,"explain":{"vi":"Chủ ngữ 建议 được mọi người chấp nhận, nên dùng 被 bị động.","en":"The suggestion is accepted by everyone, so passive 被 fits."}}]},
  {"id":"g03","title":{"zh":"连……都/也","vi":"连……都/也 (ngay cả… cũng)","en":"连…都/也 (even)"},"pattern":"S + 连 + X + 都/也 + V  /  连 + X + 都/也 + V","explain":{"vi":"Dùng để nhấn mạnh một trường hợp cực đoan: ngay cả X cũng như vậy, huống chi những cái khác. Bẫy: sau 连 X phải có 都 hoặc 也 (không dùng 还/就), và 都/也 đứng ngay trước động từ.","en":"Emphasizes an extreme case: even X is so, let alone anything else. Trap: 连 X must be followed by 都 or 也 (not 还/就), placed right before the verb."},"examples":[{"zh":"他忙得连午饭都没时间吃。","py":"Tā máng de lián wǔfàn dōu méi shíjiān chī.","vi":"Anh ấy bận đến mức ngay cả bữa trưa cũng không có thời gian ăn.","en":"He's so busy he doesn't even have time for lunch."},{"zh":"这件事连经理也不知道。","py":"Zhè jiàn shì lián jīnglǐ yě bù zhīdào.","vi":"Chuyện này ngay cả quản lý cũng không biết.","en":"Even the manager doesn't know about this."}],"quiz":[{"q":"这个问题太简单了，连新员工____会回答。","options":["就","还","才","都"],"answer":3,"explain":{"vi":"连 X phải đi với 都/也.","en":"连 X must pair with 都 or 也."}},{"q":"他来公司三个月了，____老板的名字都不知道。","options":["从","连","把","对"],"answer":1,"explain":{"vi":"Cấu trúc 连……都 nhấn mạnh 'ngay cả tên sếp'.","en":"连…都 stresses 'not even the boss's name'."}},{"q":"下面哪个句子是正确的？","options":["连他都这件事不清楚。","他连都这件事不清楚。","这件事连他都不清楚。","这件事都连他不清楚。"],"answer":2,"explain":{"vi":"Thứ tự đúng là 连 + X + 都 + động từ.","en":"The order must be 连 + X + 都 + verb."}},{"q":"我太累了，连一句话____不想说。","options":["也","还","再","就"],"answer":0,"explain":{"vi":"连 X đi với 也 (hoặc 都), không dùng 还/再/就.","en":"连 X pairs with 也 (or 都), not 还/再/就."}},{"q":"____周末他都在加班。","options":["只","连","把","才"],"answer":1,"explain":{"vi":"连 + 周末 + 都 = ngay cả cuối tuần cũng.","en":"连 + weekend + 都 means 'even on weekends'."}}]},
  {"id":"g04","title":{"zh":"除了……以外","vi":"除了……以外 (ngoài… ra / trừ…)","en":"除了…以外 (except / besides)"},"pattern":"除了 + X + (以外)，S + 都 (except) / 还·也 (besides) + V","explain":{"vi":"Đi với 都 nghĩa là 'trừ X ra' (loại X); đi với 还/也 nghĩa là 'ngoài X ra còn' (thêm vào). Bẫy: chọn 都 hay 还/也 theo nghĩa loại trừ hay bổ sung, và 还/也/都 đứng sau chủ ngữ.","en":"With 都 it means 'except X' (X excluded); with 还/也 it means 'besides X' (X plus more). Trap: choose 都 vs 还/也 by meaning, and 还/也/都 go after the subject."},"examples":[{"zh":"除了小李以外，大家都参加了会议。","py":"Chúle Xiǎo Lǐ yǐwài, dàjiā dōu cānjiā le huìyì.","vi":"Ngoài Tiểu Lý ra, mọi người đều đã tham gia cuộc họp.","en":"Everyone attended the meeting except Xiao Li."},{"zh":"除了工资以外，公司还提供午饭。","py":"Chúle gōngzī yǐwài, gōngsī hái tígōng wǔfàn.","vi":"Ngoài lương ra, công ty còn cung cấp bữa trưa.","en":"Besides the salary, the company also provides lunch."}],"quiz":[{"q":"除了周日以外，我们每天____上班。","options":["都","还","也","才"],"answer":0,"explain":{"vi":"Nghĩa loại trừ (trừ Chủ nhật) và có 每天 nên dùng 都.","en":"It means 'except Sunday' with 每天, so 都 is required."}},{"q":"除了英语以外，他____会说汉语。","options":["都","就","还","才"],"answer":2,"explain":{"vi":"Nghĩa bổ sung (ngoài tiếng Anh còn biết tiếng Trung) nên dùng 还.","en":"It adds information (besides English), so 还 is used."}},{"q":"除了小王，其他人____同意这个计划。","options":["还","都","再","才"],"answer":1,"explain":{"vi":"其他人 + 都: trừ Tiểu Vương, những người khác đều đồng ý.","en":"Excluding Xiao Wang, everyone else agrees, so 都."}},{"q":"下面哪个句子是正确的？","options":["除了面试以外，还我们要考试。","除了以外面试，我们还要考试。","除了面试以外，我们要还考试。","除了面试以外，我们还要考试。"],"answer":3,"explain":{"vi":"Cấu trúc 除了 X 以外, và 还 đứng sau chủ ngữ, trước động từ năng nguyện.","en":"X sits between 除了 and 以外, and 还 goes after the subject, before 要."}},{"q":"____工作以外，他还喜欢打篮球。","options":["因为","除了","虽然","如果"],"answer":1,"explain":{"vi":"以外 và 还 đi với 除了.","en":"以外 and 还 pair with 除了."}}]},
  {"id":"g05","title":{"zh":"不管/无论……都","vi":"不管/无论……都 (bất kể… đều)","en":"不管/无论…都 (no matter)"},"pattern":"不管/无论 + question word / A还是B / A不A，S + 都/也 + V","explain":{"vi":"Diễn tả kết quả không thay đổi trong mọi điều kiện. Bẫy: sau 不管/无论 phải có từ nghi vấn (谁, 什么, 怎么, 多…), 'A 还是 B' hoặc 'A 不 A', không dùng 或者; vế sau dùng 都/也.","en":"Shows the result stays the same under any condition. Trap: the 不管/无论 clause needs a question word (谁, 什么, 多…), 'A 还是 B' or 'A 不 A', never 或者; the second clause takes 都/也."},"examples":[{"zh":"不管多忙，她都按时交报告。","py":"Bùguǎn duō máng, tā dōu ànshí jiāo bàogào.","vi":"Dù bận đến đâu, cô ấy cũng nộp báo cáo đúng hạn.","en":"No matter how busy she is, she hands in her reports on time."},{"zh":"无论是谁，都要遵守公司的规定。","py":"Wúlùn shì shéi, dōu yào zūnshǒu gōngsī de guīdìng.","vi":"Bất kể là ai cũng đều phải tuân thủ quy định của công ty.","en":"No matter who you are, you must follow the company rules."}],"quiz":[{"q":"不管天气怎么样，他____骑车上班。","options":["就","才","再","都"],"answer":3,"explain":{"vi":"Vế sau của 不管 dùng 都.","en":"The clause after 不管 takes 都."}},{"q":"无论你同意____不同意，都要告诉我。","options":["或者","和","还是","跟"],"answer":2,"explain":{"vi":"Sau 无论 dùng 'A 还是 B', không dùng 或者.","en":"无论 takes 'A 还是 B', not 或者."}},{"q":"____遇到什么困难，我们都不能放弃。","options":["无论","虽然","因为","既然"],"answer":0,"explain":{"vi":"Có từ nghi vấn 什么 và 都 nên dùng 无论.","en":"The question word 什么 plus 都 calls for 无论."}},{"q":"下面哪个句子是正确的？","options":["不管工资高或者低，他都愿意做。","不管工资高，他都愿意做。","不管工资高低，他就愿意做。","不管工资高不高，他都愿意做。"],"answer":3,"explain":{"vi":"Sau 不管 dùng từ nghi vấn, \"A 不 A\" hoặc cặp từ trái nghĩa (高低), không dùng 或者; vế sau phải dùng 都, không dùng 就.","en":"不管 takes a question word, \"A 不 A\" or an opposite pair (高低), not 或者; the result clause needs 都, not 就."}},{"q":"不管谁打电话来，你____说我不在。","options":["才","刚","都","却"],"answer":2,"explain":{"vi":"不管 + 谁 đi với 都 ở vế sau.","en":"不管 + 谁 pairs with 都 in the second clause."}}]},
  {"id":"g06","title":{"zh":"即使……也","vi":"Cho dù … cũng","en":"Even if … still"},"pattern":"即使 + A (hypothesis), (S) + 也 + B","explain":{"vi":"Dùng để nêu một giả thiết (thường chưa xảy ra hoặc ở mức cực đoan), kết quả ở vế sau vẫn không thay đổi. Vế sau dùng 也, không dùng 就 hay 才. Bẫy thường gặp: nhầm 即使 (giả thiết) với 既然 (sự thật đã biết).","en":"Use it for a hypothesis (often unreal or extreme) that does not change the result. The second clause takes 也, not 就 or 才. Common trap: confusing 即使 (hypothesis) with 既然 (known fact)."},"examples":[{"zh":"即使工资不高，我也想留在这家公司。","py":"Jíshǐ gōngzī bù gāo, wǒ yě xiǎng liú zài zhè jiā gōngsī.","vi":"Cho dù lương không cao, tôi vẫn muốn ở lại công ty này.","en":"Even if the salary isn't high, I still want to stay at this company."},{"zh":"即使明天下雨，面试也会按时进行。","py":"Jíshǐ míngtiān xià yǔ, miànshì yě huì ànshí jìnxíng.","vi":"Cho dù ngày mai trời mưa, buổi phỏng vấn vẫn diễn ra đúng giờ.","en":"Even if it rains tomorrow, the interview will still take place on time."}],"quiz":[{"q":"____工作再忙，她也每天坚持运动。","options":["即使","因为","既然","只有"],"answer":0,"explain":{"vi":"“再忙……也” là giả thiết mức độ cao, đi với 即使.","en":"\"再忙……也\" is an extreme hypothesis, which pairs with 即使."}},{"q":"即使经理不同意，我们____要试一试。","options":["就","才","也","却"],"answer":2,"explain":{"vi":"即使 luôn đi với 也 ở vế sau.","en":"即使 is always followed by 也 in the second clause."}},{"q":"下面哪个句子是正确的？","options":["即使大家都反对，他就不会放弃。","即使大家都反对，他也不会放弃。","大家即使都反对，也他不会放弃。","即使大家都反对，他不会也放弃。"],"answer":1,"explain":{"vi":"Phải dùng 也 và 也 đứng sau chủ ngữ, trước động từ/phủ định.","en":"It must be 也, placed after the subject and before the negation/verb."}},{"q":"____只有一个人报名，培训也会按计划进行。","options":["既然","只要","即使","因为"],"answer":2,"explain":{"vi":"Giả thiết “chỉ có một người đăng ký” nhưng kết quả không đổi → 即使……也.","en":"A hypothesis that doesn't change the result → 即使……也."}},{"q":"“即使下雪，他也来上班。”这句话是什么意思？","options":["今天一定下雪了","他不来上班","下雪的时候他才来上班","下不下雪，他都会来上班"],"answer":3,"explain":{"vi":"即使……也 nghĩa là dù điều kiện thế nào kết quả vẫn vậy.","en":"即使……也 means the result holds whatever the condition."}}]},
  {"id":"g07","title":{"zh":"既然……就","vi":"Đã … thì","en":"Since (given that) … then"},"pattern":"既然 + A (known fact), (S) + 就 + B","explain":{"vi":"Dùng khi vế đầu là sự thật đã biết hoặc đã xảy ra, vế sau là kết luận, lời khuyên hay đề nghị (thường có 吧). 就 đứng sau chủ ngữ của vế sau. Bẫy: 既然 không dùng cho giả thiết, và không đi với 也 hay 但是.","en":"Use it when the first clause is a known or accepted fact and the second gives a conclusion, advice or suggestion (often with 吧). 就 goes after the subject of the second clause. Trap: 既然 is not for hypotheses and does not pair with 也 or 但是."},"examples":[{"zh":"既然你已经决定了，就早点儿告诉经理吧。","py":"Jìrán nǐ yǐjīng juédìng le, jiù zǎo diǎnr gàosu jīnglǐ ba.","vi":"Bạn đã quyết định rồi thì báo cho quản lý sớm đi.","en":"Since you've already decided, tell the manager soon."},{"zh":"既然新同事来了，你就带他熟悉一下环境吧。","py":"Jìrán xīn tóngshì lái le, nǐ jiù dài tā shúxī yíxià huánjìng ba.","vi":"Đồng nghiệp mới đã đến rồi thì bạn dẫn anh ấy làm quen với môi trường đi.","en":"Since the new colleague is here, show him around."}],"quiz":[{"q":"____大家都到了，我们就开始开会吧。","options":["即使","既然","虽然","只有"],"answer":1,"explain":{"vi":"“Mọi người đã đến” là sự thật, vế sau là đề nghị với 就 → 既然.","en":"Everyone arriving is a known fact followed by a suggestion with 就 → 既然."}},{"q":"既然你不舒服，今天____早点儿回家休息吧。","options":["就","才","而且","却"],"answer":0,"explain":{"vi":"既然 đi với 就 ở vế sau.","en":"既然 pairs with 就 in the second clause."}},{"q":"下面哪个句子是正确的？","options":["既然公司已经同意了，就你放心去吧。","公司既然已经同意了，你才放心去吧。","既然公司已经同意了，但你放心去吧。","既然公司已经同意了，你就放心去吧。"],"answer":3,"explain":{"vi":"就 phải đứng sau chủ ngữ 你, và không dùng 才/但.","en":"就 must follow the subject 你; 才 and 但 are wrong here."}},{"q":"这份工作____不适合你，你就换一份吧。","options":["即使","不但","既然","尽管"],"answer":2,"explain":{"vi":"Sự thật “không hợp” dẫn tới lời khuyên có 就 → 既然.","en":"An accepted fact leading to advice with 就 → 既然."}},{"q":"“既然你来了，就一起吃饭吧。”说话时，“你”：","options":["可能不来","还没决定来不来","来不了","已经来了"],"answer":3,"explain":{"vi":"既然 nêu sự thật đã xảy ra: người đó đã đến.","en":"既然 states a fact: the person has already come."}}]},
  {"id":"g08","title":{"zh":"只要……就 / 只有……才","vi":"Chỉ cần … là / Chỉ có … mới","en":"As long as … / Only if …"},"pattern":"只要 + A, (S) + 就 + B | 只有 + A, (S) + 才 + B","explain":{"vi":"只要 nêu điều kiện đủ (có A là đủ để có B), đi với 就. 只有 nêu điều kiện cần duy nhất (không có A thì không có B), đi với 才. Bẫy phổ biến: ghép sai cặp như 只要……才 hoặc 只有……就.","en":"只要 gives a sufficient condition (A is enough for B) and pairs with 就. 只有 gives the only necessary condition (no A, no B) and pairs with 才. Common trap: mismatched pairs like 只要……才 or 只有……就."},"examples":[{"zh":"只要你按时完成任务，就能拿到奖金。","py":"Zhǐyào nǐ ànshí wánchéng rènwu, jiù néng ná dào jiǎngjīn.","vi":"Chỉ cần bạn hoàn thành nhiệm vụ đúng hạn là sẽ nhận được thưởng.","en":"As long as you finish your tasks on time, you'll get the bonus."},{"zh":"只有通过面试，才能来我们公司工作。","py":"Zhǐyǒu tōngguò miànshì, cái néng lái wǒmen gōngsī gōngzuò.","vi":"Chỉ có vượt qua phỏng vấn mới được vào làm ở công ty chúng tôi.","en":"Only by passing the interview can you work at our company."}],"quiz":[{"q":"只要你有问题，____可以随时来找我。","options":["才","就","而且","却"],"answer":1,"explain":{"vi":"只要 đi với 就.","en":"只要 pairs with 就."}},{"q":"____经理同意，你才能请三天以上的假。","options":["只要","既然","只有","即使"],"answer":2,"explain":{"vi":"Vế sau có 才 → điều kiện cần duy nhất 只有.","en":"The second clause has 才, so the necessary condition 只有 is needed."}},{"q":"只要多练习，你的汉语____会越来越好。","options":["就","才","却","但"],"answer":0,"explain":{"vi":"只要……就: luyện nhiều là đủ để tiến bộ.","en":"只要……就: practising is enough to improve."}},{"q":"下面哪个句子是正确的？","options":["只要提前申请，才能参加这次培训。","只有提前申请，就能参加这次培训。","只有提前申请，能才参加这次培训。","只有提前申请，才能参加这次培训。"],"answer":3,"explain":{"vi":"只有 đi với 才, và 才 đứng trước động từ năng nguyện 能.","en":"只有 pairs with 才, and 才 comes before the modal 能."}},{"q":"“只有周末，他才有时间陪家人。”这句话的意思是：","options":["他周末没有时间","他只在周末有时间陪家人","他每天都陪家人","周末他要加班"],"answer":1,"explain":{"vi":"只有……才 nghĩa là chỉ trong điều kiện đó (cuối tuần) mới có.","en":"只有……才 means only under that condition (weekends)."}}]},
  {"id":"g09","title":{"zh":"不但/不仅……而且/还/也","vi":"Không những … mà còn","en":"Not only … but also"},"pattern":"(S) + 不但/不仅 + A, 而且 + (S) + 还/也 + B","explain":{"vi":"Dùng để thêm một ý ở mức cao hơn. Hai vế cùng chủ ngữ thì chủ ngữ đứng trước 不但; khác chủ ngữ thì 不但 đứng trước chủ ngữ thứ nhất. Bẫy: 而且 đứng đầu vế sau, còn 还/也 phải đứng sau chủ ngữ của vế sau.","en":"Use it to add a further, stronger point. With one subject, the subject goes before 不但; with two subjects, 不但 goes before the first subject. Trap: 而且 starts the second clause, but 还/也 must come after its subject."},"examples":[{"zh":"她不但会说英语，而且汉语也说得很好。","py":"Tā búdàn huì shuō Yīngyǔ, érqiě Hànyǔ yě shuō de hěn hǎo.","vi":"Cô ấy không những biết nói tiếng Anh mà tiếng Trung cũng nói rất giỏi.","en":"She not only speaks English, but also speaks Chinese very well."},{"zh":"这家公司不仅工资高，而且离我家很近。","py":"Zhè jiā gōngsī bùjǐn gōngzī gāo, érqiě lí wǒ jiā hěn jìn.","vi":"Công ty này không những lương cao mà còn gần nhà tôi.","en":"This company not only pays well but is also close to my home."}],"quiz":[{"q":"小王不但工作认真，____经常帮助同事。","options":["而且","却","才","就"],"answer":0,"explain":{"vi":"不但 đi với 而且 để thêm ý.","en":"不但 pairs with 而且 to add a point."}},{"q":"这次培训不仅有中国员工参加，越南员工____参加了。","options":["才","也","就","却"],"answer":1,"explain":{"vi":"不仅……也: thêm một đối tượng nữa, 也 đứng sau chủ ngữ.","en":"不仅……也 adds another subject; 也 follows that subject."}},{"q":"下面哪个句子是正确的？","options":["不但他来了，他的经理而且也来了。","他不但来了，但是他的经理也来了。","不但他来了，而且他的经理也来了。","不但他来了，而且也他的经理来了。"],"answer":2,"explain":{"vi":"Hai chủ ngữ khác nhau: 不但 đứng trước chủ ngữ, 而且 đầu vế sau, 也 sau chủ ngữ.","en":"Two subjects: 不但 before the first subject, 而且 opens clause two, 也 after its subject."}},{"q":"这个方法____简单，而且很有效。","options":["虽然","只要","既然","不但"],"answer":3,"explain":{"vi":"Vế sau có 而且 để tăng tiến → 不但.","en":"而且 in the second clause signals 不但 in the first."}},{"q":"“这家公司不仅工资高，还常常组织旅游。”下面哪个说法对？","options":["公司工资高，也有旅游活动","公司工资不高","公司从来不组织旅游","员工只有工资，没有活动"],"answer":0,"explain":{"vi":"不仅……还 nghĩa là có cả hai điều.","en":"不仅……还 means both things are true."}}]},
  {"id":"g10","title":{"zh":"虽然/尽管……但是/可是/却","vi":"Mặc dù … nhưng","en":"Although … but"},"pattern":"虽然/尽管 + A, 但是/可是 + B | 虽然/尽管 + A, S + 却 + V","explain":{"vi":"Nêu sự nhượng bộ: A là sự thật nhưng B trái với mong đợi. Khác tiếng Anh, tiếng Trung thường dùng cả hai vế 虽然……但是. Bẫy: 却 là phó từ, phải đứng sau chủ ngữ, không đứng đầu vế như 但是.","en":"Expresses concession: A is true, yet B is unexpected. Unlike English, Chinese usually keeps both parts, 虽然……但是. Trap: 却 is an adverb and must follow the subject, not start the clause like 但是."},"examples":[{"zh":"虽然这份工作很累，但是我学到了很多。","py":"Suīrán zhè fèn gōngzuò hěn lèi, dànshì wǒ xuédào le hěn duō.","vi":"Mặc dù công việc này rất mệt nhưng tôi đã học được rất nhiều.","en":"Although this job is tiring, I've learned a lot."},{"zh":"尽管他经验不多，面试结果却很好。","py":"Jǐnguǎn tā jīngyàn bù duō, miànshì jiéguǒ què hěn hǎo.","vi":"Mặc dù anh ấy không nhiều kinh nghiệm nhưng kết quả phỏng vấn lại rất tốt.","en":"Although he doesn't have much experience, his interview went very well."}],"quiz":[{"q":"虽然今天是周末，____很多同事还在公司加班。","options":["但是","而且","所以","就"],"answer":0,"explain":{"vi":"虽然 đi với 但是 để chỉ sự trái ngược.","en":"虽然 pairs with 但是 to show contrast."}},{"q":"尽管天气不好，他____按时到了公司。","options":["但是","而且","却","才"],"answer":2,"explain":{"vi":"Chỗ trống ở sau chủ ngữ 他 nên dùng phó từ 却, không dùng 但是.","en":"The blank follows the subject 他, so the adverb 却 fits, not 但是."}},{"q":"下面哪个句子是正确的？","options":["我很想去，却时间不够。","虽然我很想去，时间但是不够。","虽然我很想去，所以时间不够。","我很想去，时间却不够。"],"answer":3,"explain":{"vi":"却 phải đứng sau chủ ngữ 时间.","en":"却 must come after the subject 时间."}},{"q":"____我给他打了三次电话，可是他一直没接。","options":["因为","尽管","只要","既然"],"answer":1,"explain":{"vi":"Vế sau có 可是 chỉ sự trái ngược → 尽管.","en":"可是 in the second clause shows contrast → 尽管."}},{"q":"他虽然年轻，____很有管理经验。","options":["就","而且","所以","但是"],"answer":3,"explain":{"vi":"虽然……但是: trẻ nhưng có kinh nghiệm quản lý.","en":"虽然……但是: young, yet experienced in management."}}]},
  {"id":"g11","title":{"zh":"因为……所以 / 由于……因此","vi":"Quan hệ nguyên nhân – kết quả","en":"Cause and effect"},"pattern":"因为/由于 + reason, 所以/因此 + result  |  result, 因为 + reason","explain":{"vi":"Dùng để nói nguyên nhân và kết quả; 由于……因此 trang trọng hơn, hay dùng trong văn bản công việc. Bẫy thường gặp: ghép sai cặp liên từ (因为……但是) hoặc dùng 所以/因此 để nêu lý do ở vế sau – vế sau nêu lý do phải dùng 因为.","en":"Expresses cause and effect; 由于……因此 is more formal and common in written work documents. Common trap: pairing the wrong connectors (因为……但是) or using 所以/因此 to give a reason in the second clause – a reason placed second needs 因为."},"examples":[{"zh":"因为收入太低，所以他决定换工作。","py":"Yīnwèi shōurù tài dī, suǒyǐ tā juédìng huàn gōngzuò.","vi":"Vì thu nhập quá thấp nên anh ấy quyết định đổi việc.","en":"Because his income was too low, he decided to change jobs."},{"zh":"由于人数不够，因此会议改到下周。","py":"Yóuyú rénshù bú gòu, yīncǐ huìyì gǎi dào xià zhōu.","vi":"Do không đủ người nên cuộc họp được dời sang tuần sau.","en":"Due to insufficient attendance, the meeting was moved to next week."}],"quiz":[{"q":"____路上堵车，所以他今天迟到了。","options":["因为","虽然","如果","而且"],"answer":0,"explain":{"vi":"Vế sau có 所以 nên vế trước dùng 因为 để nêu nguyên nhân.","en":"所以 in the second clause pairs with 因为 giving the reason."}},{"q":"由于应聘的人很多，____面试要分两天进行。","options":["但是","因此","虽然","即使"],"answer":1,"explain":{"vi":"由于 thường đi với 因此 để nêu kết quả.","en":"由于 is usually paired with 因此 to state the result."}},{"q":"选出正确的句子。","options":["虽然他工作很努力，所以经理对他很满意。","因为他工作很努力，但是经理对他很满意。","因为他工作很努力，而且经理对他很满意。","因为他工作很努力，所以经理对他很满意。"],"answer":3,"explain":{"vi":"Chỉ có cặp 因为……所以 là đúng; các câu khác ghép sai liên từ.","en":"Only 因为……所以 is a correct pair; the others mismatch connectors."}},{"q":"因为明天是国庆节，____公司放假一天。","options":["而且","可是","所以","或者"],"answer":2,"explain":{"vi":"Nghỉ lễ là kết quả của ngày Quốc khánh nên dùng 所以.","en":"The day off is the result of the holiday, so 所以 fits."}},{"q":"他今天没来上班，____他生病了。","options":["所以","因此","于是","因为"],"answer":3,"explain":{"vi":"Vế sau nêu lý do nên phải dùng 因为, không dùng 所以/因此/于是.","en":"The second clause gives the reason, so it needs 因为, not a result word."}}]},
  {"id":"g12","title":{"zh":"如果/要是……（的话）就 / 否则","vi":"Câu điều kiện và \"nếu không thì\"","en":"Conditionals and \"otherwise\""},"pattern":"如果/要是 + condition (的话), (subject) 就 + result  |  A, 否则 + bad result","explain":{"vi":"如果/要是 nêu điều kiện, vế sau thường có 就; 否则 nghĩa là \"nếu không thì\", đặt ở đầu vế sau để nói hậu quả. Bẫy thường gặp: 就 là phó từ nên phải đứng sau chủ ngữ (我们就……, không nói 就我们……), và không dùng 所以 sau 如果.","en":"如果/要是 introduces a condition and the result clause usually has 就; 否则 means \"otherwise\" and starts the clause stating the consequence. Common trap: 就 is an adverb, so it goes after the subject (我们就……, not 就我们……), and 所以 does not follow 如果."},"examples":[{"zh":"如果你有问题，就给我打电话吧。","py":"Rúguǒ nǐ yǒu wèntí, jiù gěi wǒ dǎ diànhuà ba.","vi":"Nếu bạn có vấn đề gì thì cứ gọi điện cho tôi nhé.","en":"If you have any questions, just give me a call."},{"zh":"请按时交材料，否则会影响你的应聘。","py":"Qǐng ànshí jiāo cáiliào, fǒuzé huì yǐngxiǎng nǐ de yìngpìn.","vi":"Vui lòng nộp hồ sơ đúng hạn, nếu không sẽ ảnh hưởng đến việc ứng tuyển của bạn.","en":"Please submit your documents on time, otherwise it will affect your application."}],"quiz":[{"q":"____明天下雨的话，我们就在办公室开会。","options":["因为","要是","虽然","不但"],"answer":1,"explain":{"vi":"Có 的话 và 就 nên vế trước là điều kiện, dùng 要是.","en":"的话 and 就 mark a condition, so 要是 fits."}},{"q":"你最好早点儿出发，____会迟到的。","options":["所以","而且","因此","否则"],"answer":3,"explain":{"vi":"否则 = nếu không thì; nói hậu quả khi không làm theo lời khuyên.","en":"否则 means \"otherwise\", giving the consequence of not following the advice."}},{"q":"如果你对工作有什么意见，____直接告诉经理。","options":["就","才","过","又"],"answer":0,"explain":{"vi":"如果 đi với 就 để nêu kết quả.","en":"如果 pairs with 就 in the result clause."}},{"q":"选出正确的句子。","options":["要是你明天没空，就我们改到周五。","如果你明天没空，所以我们改到周五。","要是你明天没空，我们就改到周五。","你明天要是没空，我们否则改到周五。"],"answer":2,"explain":{"vi":"就 phải đứng sau chủ ngữ 我们; 如果 không đi với 所以.","en":"就 must follow the subject 我们; 如果 does not pair with 所以."}},{"q":"这些材料必须今天整理好，____明天的会议就没法开了。","options":["否则","如果","因为","要是"],"answer":0,"explain":{"vi":"Vế sau nói hậu quả nếu không làm xong nên dùng 否则.","en":"The clause states what happens if it isn't done, so 否则 fits."}}]},
  {"id":"g13","title":{"zh":"结果补语","vi":"Bổ ngữ kết quả","en":"Result complements"},"pattern":"V + 完/好/到/懂/错/清楚/干净 (+ 了) + O  |  没 + V + result","explain":{"vi":"Bổ ngữ kết quả đứng ngay sau động từ, cho biết kết quả của hành động (xem xong, viết sai, nghe hiểu). Bẫy thường gặp: phủ định dùng 没 chứ không dùng 不, câu có 没 thì bỏ 了, và không được chen tân ngữ vào giữa động từ và bổ ngữ.","en":"A result complement follows the verb directly and shows the outcome (finished reading, wrote wrongly, understood). Common trap: negate with 没, not 不, drop 了 after 没, and never put the object between the verb and the complement."},"examples":[{"zh":"我已经看完了这些应聘者的材料。","py":"Wǒ yǐjīng kàn wán le zhèxiē yìngpìnzhě de cáiliào.","vi":"Tôi đã xem xong hồ sơ của những ứng viên này.","en":"I have already finished reading these applicants' documents."},{"zh":"对不起，我把新同事的名字写错了。","py":"Duìbuqǐ, wǒ bǎ xīn tóngshì de míngzi xiě cuò le.","vi":"Xin lỗi, tôi viết sai tên của đồng nghiệp mới rồi.","en":"Sorry, I wrote the new colleague's name wrong."}],"quiz":[{"q":"这个问题你听____了吗？","options":["懂","着","起","在"],"answer":0,"explain":{"vi":"听懂 = nghe hiểu, là bổ ngữ kết quả phù hợp.","en":"听懂 (hear and understand) is the fitting result complement."}},{"q":"选出正确的句子。","options":["我不做完这个工作了。","我还没做完这个工作。","我还没做完了这个工作。","我还没做这个工作完。"],"answer":1,"explain":{"vi":"Phủ định dùng 没, bỏ 了, và bổ ngữ 完 đứng ngay sau động từ.","en":"Negate with 没, drop 了, and keep 完 right after the verb."}},{"q":"请把会议室打扫____，下午有客人来。","options":["高兴","认真","干净","清楚"],"answer":2,"explain":{"vi":"打扫干净 = dọn sạch sẽ.","en":"打扫干净 means to clean something until it is clean."}},{"q":"你说得太快了，我没听____。","options":["干净","完成","好看","清楚"],"answer":3,"explain":{"vi":"听清楚 = nghe rõ.","en":"听清楚 means to hear clearly."}},{"q":"我找了半天，终于找____那份材料了。","options":["到","懂","干净","清楚"],"answer":0,"explain":{"vi":"找到 = tìm thấy, hợp với 终于.","en":"找到 means to find successfully, matching 终于."}}]},
  {"id":"g14","title":{"zh":"趋向补语（含引申义）","vi":"Bổ ngữ xu hướng (kể cả nghĩa mở rộng)","en":"Directional complements (incl. extended meanings)"},"pattern":"V + 起来/下去/出来/下来/上  |  V + 进/回 + place + 来/去","explain":{"vi":"Ngoài chỉ hướng, các bổ ngữ này có nghĩa mở rộng: 看起来 (trông có vẻ), 想起来 (nhớ ra), 坚持下去 (tiếp tục), 看出来/听出来 (nhận ra), 停下来 (dừng lại). Bẫy thường gặp: nhầm 起来/出来/下去, và tân ngữ chỉ nơi chốn phải đặt trước 来/去 (走进办公室来).","en":"Besides direction, these complements have extended meanings: 看起来 (seems), 想起来 (recall), 坚持下去 (keep going), 看出来/听出来 (recognise), 停下来 (stop). Common trap: mixing up 起来/出来/下去, and a place object must go before 来/去 (走进办公室来)."},"examples":[{"zh":"这个办法听起来不错，我们试试吧。","py":"Zhège bànfǎ tīng qǐlai búcuò, wǒmen shìshi ba.","vi":"Cách này nghe có vẻ hay đấy, chúng ta thử xem.","en":"This method sounds good, let's give it a try."},{"zh":"我想起来了，他是上周来应聘的。","py":"Wǒ xiǎng qǐlai le, tā shì shàng zhōu lái yìngpìn de.","vi":"Tôi nhớ ra rồi, anh ấy đến ứng tuyển tuần trước.","en":"Now I remember, he came to apply last week."}],"quiz":[{"q":"他今天看____很高兴。","options":["出来","下去","起来","过来"],"answer":2,"explain":{"vi":"看起来 = trông có vẻ, dùng để nhận xét bề ngoài.","en":"看起来 means \"looks/seems\", used to judge appearance."}},{"q":"虽然工作很辛苦，但是我会坚持____的。","options":["下去","起来","出来","过去"],"answer":0,"explain":{"vi":"坚持下去 = tiếp tục kiên trì.","en":"坚持下去 means to keep on persisting."}},{"q":"车在公司门口停了____。","options":["起来","下来","出来","下去"],"answer":1,"explain":{"vi":"停下来 = dừng lại, 下来 chỉ động tác dừng.","en":"停下来 means to come to a stop."}},{"q":"我听____了，这是王经理的声音。","options":["下去","起来","过来","出来"],"answer":3,"explain":{"vi":"听出来 = nghe ra, nhận ra qua âm thanh.","en":"听出来 means to recognise by listening."}},{"q":"选出正确的句子。","options":["他走进来办公室了。","他走办公室进来了。","他走进办公室来了。","他进来走办公室了。"],"answer":2,"explain":{"vi":"Tân ngữ chỉ nơi chốn đặt giữa 进 và 来.","en":"The place object goes between 进 and 来."}}]},
  {"id":"g15","title":{"zh":"可能补语","vi":"Bổ ngữ khả năng","en":"Potential complements"},"pattern":"V + 得/不 + result/direction  (看不懂, 来不及, 买得到, 受不了)","explain":{"vi":"Dùng để nói có thể hay không thể đạt được kết quả: V得 + bổ ngữ (được), V不 + bổ ngữ (không được). Bẫy thường gặp: không dùng chung với câu chữ 把 hay với 能 ở dạng phủ định (không nói 能做不完), và 得/不 luôn đứng giữa động từ và bổ ngữ.","en":"Shows whether a result can be achieved: V得 + complement (can), V不 + complement (cannot). Common trap: it cannot be used in a 把 sentence or with 能 in the negative (not 能做不完), and 得/不 always sits between the verb and the complement."},"examples":[{"zh":"这么多工作，我今天做不完。","py":"Zhème duō gōngzuò, wǒ jīntiān zuò bu wán.","vi":"Nhiều việc thế này, hôm nay tôi làm không xong.","en":"With this much work, I can't finish it today."},{"zh":"现在出发还来得及，别着急。","py":"Xiànzài chūfā hái láidejí, bié zháojí.","vi":"Bây giờ xuất phát vẫn còn kịp, đừng lo.","en":"If we leave now we can still make it, don't worry."}],"quiz":[{"q":"他说的是上海话，我听____。","options":["不懂","得不懂","不得懂","没得懂"],"answer":0,"explain":{"vi":"听不懂 = nghe không hiểu; 不 đứng giữa động từ và bổ ngữ.","en":"听不懂 means cannot understand; 不 sits between verb and complement."}},{"q":"会议九点开始，现在八点五十了，我们还来____吗？","options":["及得","得及","不得及","得了及"],"answer":1,"explain":{"vi":"Dạng khẳng định đúng là 来得及 (còn kịp).","en":"The correct positive form is 来得及 (still in time)."}},{"q":"这本书在附近的书店买____，你可以在网上买。","options":["得到","没到","不到","到不"],"answer":2,"explain":{"vi":"买不到 = không mua được, nên mới phải mua trên mạng.","en":"买不到 means cannot buy it, hence buying online."}},{"q":"选出正确的句子。","options":["这些工作我把它做不完。","这些工作我能做不完。","这些工作我做完不了。","这些工作我一个人做不完。"],"answer":3,"explain":{"vi":"Bổ ngữ khả năng không dùng với 把 hay 能; 做不完 là đúng.","en":"Potential complements don't combine with 把 or 能; 做不完 is correct."}},{"q":"他每天加班到十一点，身体快受____了。","options":["不了","得了","不完","不到"],"answer":0,"explain":{"vi":"受不了 = chịu không nổi.","en":"受不了 means cannot bear it."}}]},
  {"id":"g16","title":{"zh":"程度补语","vi":"Bổ ngữ trình độ","en":"Degree complements"},"pattern":"V/Adj + 得 + (很) Adj ; V + O + V + 得 + Adj ; Adj + 极了 / 得很 / 死了","explain":{"vi":"Dùng để đánh giá mức độ, kết quả của hành động hoặc tính chất. Nếu có tân ngữ, phải lặp lại động từ (说汉语说得很好) hoặc đưa tân ngữ lên trước. Bẫy thường gặp: nhầm 得 với 的/地, và phủ định đặt 不 sau 得 (来得不早), không đặt trước động từ.","en":"Used to comment on how well/how much an action is done or how strong a quality is. With an object, repeat the verb (说汉语说得很好) or front the object. Common trap: confusing 得 with 的/地, and putting 不 before the verb instead of after 得 (来得不早)."},"examples":[{"zh":"她英语说得很流利。","py":"Tā Yīngyǔ shuō de hěn liúlì.","vi":"Cô ấy nói tiếng Anh rất lưu loát.","en":"She speaks English very fluently."},{"zh":"这个月招聘的人多极了，我忙死了。","py":"Zhège yuè zhāopìn de rén duō jí le, wǒ máng sǐ le.","vi":"Tháng này tuyển rất nhiều người, tôi bận chết đi được.","en":"We're hiring a huge number of people this month; I'm insanely busy."}],"quiz":[{"q":"小王工作做____很认真。","options":["得","的","地","了"],"answer":0,"explain":{"vi":"Sau động từ, trước phần đánh giá mức độ dùng 得.","en":"得 links a verb to its degree complement."}},{"q":"选择正确的句子。","options":["他说汉语得很好。","他说汉语说得很好。","他说得汉语很好。","他汉语说很好得。"],"answer":1,"explain":{"vi":"Có tân ngữ thì lặp lại động từ: V + O + V + 得.","en":"With an object, repeat the verb: V + O + V + 得."}},{"q":"这次培训的内容有意思____。","options":["很","非常","极了","得"],"answer":2,"explain":{"vi":"极了 đứng sau tính từ để chỉ mức độ cao nhất; 很/非常 phải đứng trước.","en":"极了 follows the adjective; 很/非常 must go before it."}},{"q":"经理今天忙____，连午饭都没吃。","options":["很","非常","真","得很"],"answer":3,"explain":{"vi":"Adj + 得很 là bổ ngữ trình độ; 很/非常/真 không đứng sau tính từ.","en":"Adj + 得很 is a degree complement; 很/非常/真 cannot follow the adjective."}},{"q":"选择正确的句子。","options":["他不来得早。","他没来得早。","他来得不早。","他来不得早。"],"answer":2,"explain":{"vi":"Phủ định bổ ngữ trình độ: đặt 不 sau 得.","en":"Negate a degree complement by putting 不 after 得."}}]},
  {"id":"g17","title":{"zh":"是……的（强调）","vi":"Cấu trúc 是……的 (nhấn mạnh)","en":"是……的 for emphasis"},"pattern":"S + (是) + 时间/地点/方式/目的 + V (+ O) + 的 ; 不是……的","explain":{"vi":"Dùng khi hành động đã xảy ra, người nói nhấn mạnh thời gian, địa điểm, cách thức hoặc mục đích. Phủ định là 不是……的. Bẫy thường gặp: không dùng 了/过 trong câu 是……的, và không dùng cho việc tương lai.","en":"Used when an action already happened and you stress when, where, how or why it happened. The negative is 不是……的. Common trap: no 了/过 inside 是……的, and it is not used for future actions."},"examples":[{"zh":"我是去年三月进公司的。","py":"Wǒ shì qùnián sān yuè jìn gōngsī de.","vi":"Tôi vào công ty từ tháng ba năm ngoái.","en":"I joined the company last March."},{"zh":"新同事是坐飞机从河内来的。","py":"Xīn tóngshì shì zuò fēijī cóng Hénèi lái de.","vi":"Đồng nghiệp mới bay từ Hà Nội đến.","en":"The new colleague came from Hanoi by plane."}],"quiz":[{"q":"你是什么时候来公司____？","options":["了","的","过","着"],"answer":1,"explain":{"vi":"Hỏi thời gian của việc đã xảy ra dùng 是……的.","en":"Asking when a past action happened uses 是……的."}},{"q":"选择正确的句子。","options":["我是昨天到了北京的。","我是昨天到北京过的。","我是昨天到北京的。","我昨天是到北京了的。"],"answer":2,"explain":{"vi":"Trong 是……的 không dùng 了 hay 过.","en":"是……的 does not take 了 or 过."}},{"q":"这份合同____小李签的，是经理签的。","options":["不","没有","没","不是"],"answer":3,"explain":{"vi":"Phủ định của 是……的 là 不是……的.","en":"The negative of 是……的 is 不是……的."}},{"q":"A：你是怎么知道这个职位的？ B：____","options":["我是在网上看到的。","我在网上看到的了。","我是在网上看到了。","我是在网上看的到。"],"answer":0,"explain":{"vi":"Trả lời theo đúng khung 是 + nơi chốn/cách thức + V + 的.","en":"The answer keeps the frame 是 + place/means + V + 的."}},{"q":"我们是在会议室____面试的。","options":["进行了","进行","进行过","正在进行"],"answer":1,"explain":{"vi":"Động từ trong 是……的 không kèm 了/过/正在.","en":"The verb in 是……的 takes no 了/过/正在."}}]},
  {"id":"g18","title":{"zh":"越来越 / 越……越……","vi":"Càng ngày càng / càng… càng…","en":"More and more / the more… the more…"},"pattern":"S + 越来越 + Adj/V ; (S) + 越 + V1 + (S) + 越 + Adj/V2","explain":{"vi":"越来越 diễn tả sự thay đổi dần theo thời gian; 越A越B nghĩa là B thay đổi theo A. Bẫy thường gặp: sau 越来越 không thêm 很/非常/更/太.","en":"越来越 shows gradual change over time; 越A越B means B changes as A increases. Common trap: never put 很/非常/更/太 after 越来越."},"examples":[{"zh":"公司的员工越来越多了。","py":"Gōngsī de yuángōng yuè lái yuè duō le.","vi":"Nhân viên của công ty ngày càng nhiều.","en":"The company has more and more employees."},{"zh":"这个问题我越想越觉得奇怪。","py":"Zhège wèntí wǒ yuè xiǎng yuè juéde qíguài.","vi":"Vấn đề này tôi càng nghĩ càng thấy lạ.","en":"The more I think about this problem, the stranger it seems."}],"quiz":[{"q":"天气越来越____了。","options":["很冷","冷","非常冷","太冷"],"answer":1,"explain":{"vi":"Sau 越来越 dùng tính từ trơn, không thêm phó từ mức độ.","en":"越来越 takes a bare adjective, no degree adverb."}},{"q":"他的汉语越说越____。","options":["流利","很流利","更流利","最流利"],"answer":0,"explain":{"vi":"越……越 đã chỉ mức độ, không thêm 很/更/最.","en":"越……越 already shows degree; no 很/更/最."}},{"q":"选择正确的句子。","options":["工作越来越很忙了。","工作越越来忙了。","工作越来越更忙了。","工作越来越忙了。"],"answer":3,"explain":{"vi":"越来越 + tính từ trơn là đúng.","en":"越来越 + bare adjective is correct."}},{"q":"这份工作我____做越喜欢。","options":["越来","更","越","很"],"answer":2,"explain":{"vi":"Cấu trúc 越 + V + 越 + V/Adj.","en":"The pattern is 越 + V + 越 + V/Adj."}},{"q":"我们公司的业务____好。","options":["越越","越来越","更加越","越是来"],"answer":1,"explain":{"vi":"Chỉ sự thay đổi dần theo thời gian dùng 越来越.","en":"Gradual change over time uses 越来越."}}]},
  {"id":"g19","title":{"zh":"比较句","vi":"Câu so sánh","en":"Comparative sentences"},"pattern":"A 比 B + (更/还) Adj (+ 一点儿/多了/得多) ; A 没有 B (那么/这么) Adj ; A 跟 B 一样 (Adj) ; A 不如 B (Adj)","explain":{"vi":"比 dùng để so sánh hơn; 没有…那么 và 不如 so sánh kém; 跟…一样 so sánh bằng. Bẫy thường gặp: trong câu 比 không dùng 很/非常/太, chỉ dùng 更/还; mức chênh lệch (一点儿/多了) đặt sau tính từ.","en":"比 expresses 'more than'; 没有…那么 and 不如 express 'not as… as'; 跟…一样 expresses equality. Common trap: 比 sentences cannot use 很/非常/太, only 更/还; the difference (一点儿/多了) goes after the adjective."},"examples":[{"zh":"这个月的工资比上个月多一点儿。","py":"Zhège yuè de gōngzī bǐ shàng ge yuè duō yìdiǎnr.","vi":"Lương tháng này nhiều hơn tháng trước một chút.","en":"This month's salary is a bit higher than last month's."},{"zh":"新办公室没有旧的那么大。","py":"Xīn bàngōngshì méiyǒu jiù de nàme dà.","vi":"Văn phòng mới không rộng bằng văn phòng cũ.","en":"The new office isn't as big as the old one."}],"quiz":[{"q":"今天比昨天____热。","options":["更","很","非常","太"],"answer":0,"explain":{"vi":"Trong câu 比 chỉ dùng 更/还 trước tính từ.","en":"Only 更/还 can precede the adjective in a 比 sentence."}},{"q":"小张的经验____小李那么丰富。","options":["不比","比","没有","跟"],"answer":2,"explain":{"vi":"没有 + B + 那么 + Adj là so sánh kém.","en":"没有 + B + 那么 + Adj means 'not as… as'."}},{"q":"他的想法跟我的____。","options":["一起","那么","比较","一样"],"answer":3,"explain":{"vi":"So sánh bằng dùng 跟……一样.","en":"Equality uses 跟……一样."}},{"q":"选择正确的句子。","options":["这家公司比那家很大。","这家公司比那家非常大。","这家公司比那家大得多。","这家公司大比那家多了。"],"answer":2,"explain":{"vi":"Mức chênh lệch 得多 đặt sau tính từ; không dùng 很/非常.","en":"得多 goes after the adjective; 很/非常 are not allowed."}},{"q":"坐地铁____打车方便。","options":["跟","越","很","不如"],"answer":3,"explain":{"vi":"A 不如 B + Adj nghĩa là A kém B.","en":"A 不如 B + Adj means A is less… than B."}}]},
  {"id":"g20","title":{"zh":"动量补语与时量补语","vi":"Bổ ngữ động lượng và bổ ngữ thời lượng","en":"Verb-measure and duration complements"},"pattern":"V + 了/过 + 数 + 次/遍/趟/下 ; V + 了 + 时段 (+ 的) + O ; V + O + V + 了 + 时段 ; V + 代词 + 数 + 次","explain":{"vi":"次/遍/趟/下 chỉ số lần của hành động; thời lượng chỉ hành động kéo dài bao lâu. Bẫy thường gặp: tân ngữ danh từ đặt sau bổ ngữ (学了两年汉语) hoặc lặp động từ, còn đại từ đặt trước (见过他一次).","en":"次/遍/趟/下 count how many times an action happens; a duration says how long it lasts. Common trap: a noun object goes after the complement (学了两年汉语) or the verb is repeated, but a pronoun goes before it (见过他一次)."},"examples":[{"zh":"这份材料我已经看了两遍了。","py":"Zhè fèn cáiliào wǒ yǐjīng kàn le liǎng biàn le.","vi":"Tài liệu này tôi đã đọc hai lượt rồi.","en":"I've already read this document twice."},{"zh":"我昨天开会开了三个小时。","py":"Wǒ zuótiān kāi huì kāi le sān ge xiǎoshí.","vi":"Hôm qua tôi họp mất ba tiếng.","en":"Yesterday I was in a meeting for three hours."}],"quiz":[{"q":"请你把这份合同再检查一____。","options":["遍","趟","块","本"],"answer":0,"explain":{"vi":"遍 chỉ làm lại từ đầu đến cuối một lượt.","en":"遍 means once through from start to finish."}},{"q":"我明天要去银行一____。","options":["遍","趟","张","件"],"answer":1,"explain":{"vi":"趟 dùng cho một chuyến đi đi về về.","en":"趟 counts a round trip somewhere."}},{"q":"选择正确的句子。","options":["我学汉语了两年。","我两年学了汉语。","我学了两年汉语。","我学两年了汉语。"],"answer":2,"explain":{"vi":"Tân ngữ danh từ đứng sau bổ ngữ thời lượng.","en":"A noun object follows the duration complement."}},{"q":"选择正确的句子。","options":["我见过一次他。","我一次见过他。","我见他过一次。","我见过他一次。"],"answer":3,"explain":{"vi":"Tân ngữ là đại từ đặt trước bổ ngữ động lượng.","en":"A pronoun object goes before the verb-measure complement."}},{"q":"昨天的会议开____两个小时。","options":["着","在","了","得"],"answer":2,"explain":{"vi":"Hành động đã hoàn thành kéo dài bao lâu: V + 了 + thời lượng.","en":"A completed action's duration: V + 了 + time span."}}]},
  {"id":"g21","title":{"zh":"疑问代词活用","vi":"Đại từ nghi vấn dùng với nghĩa phiếm chỉ","en":"Question words used as indefinites"},"pattern":"谁/什么/哪儿 + 都/也 + (不/没) V ; 怎么也 + V不… ; V + 什么 + 就 + V + 什么","explain":{"vi":"Đại từ nghi vấn + 都/也 mang nghĩa \"ai cũng / gì cũng / đâu cũng\"; cấu trúc lặp \"想V什么就V什么\" nghĩa là \"muốn gì thì làm nấy\". Bẫy hay gặp: 都/也 phải đứng sau đại từ và trước động từ, và \"怎么也\" thường đi với bổ ngữ khả năng phủ định (怎么也打不通).","en":"A question word + 都/也 means \"everyone / everything / everywhere\"; the repeated form \"想V什么就V什么\" means \"do whatever you want\". Common trap: 都/也 must come after the question word and before the verb, and 怎么也 usually pairs with a negative potential complement (怎么也打不通)."},"examples":[{"zh":"这件事谁都不知道，你别担心。","py":"Zhè jiàn shì shéi dōu bù zhīdào, nǐ bié dānxīn.","vi":"Chuyện này không ai biết cả, bạn đừng lo.","en":"Nobody knows about this, don't worry."},{"zh":"新员工想问什么就问什么。","py":"Xīn yuángōng xiǎng wèn shénme jiù wèn shénme.","vi":"Nhân viên mới muốn hỏi gì thì cứ hỏi nấy.","en":"New employees can ask whatever they want to ask."}],"quiz":[{"q":"我给他打了好几次电话，____也打不通。","options":["什么","多少","怎么","几"],"answer":2,"explain":{"vi":"\"怎么也 + V不…\" nghĩa là làm cách nào cũng không được.","en":"\"怎么也 + V不…\" means it fails no matter how you try."}},{"q":"周末你想去____，我们就去哪儿。","options":["哪儿","什么","谁","怎么"],"answer":0,"explain":{"vi":"Cấu trúc lặp phải dùng cùng một đại từ: 去哪儿…就去哪儿.","en":"The repeated structure needs the same question word: 去哪儿…就去哪儿."}},{"q":"下面哪个句子是对的？","options":["这个办法都谁知道。","这个办法知道谁都。","谁这个办法知道都。","这个办法谁都知道。"],"answer":3,"explain":{"vi":"Trật tự đúng là: đại từ nghi vấn + 都 + động từ.","en":"The correct order is question word + 都 + verb."}},{"q":"他今天很忙，____都没去，一直在办公室。","options":["什么","谁","哪儿","怎么"],"answer":2,"explain":{"vi":"\"哪儿都没去\" = không đi đâu cả, hợp với \"一直在办公室\".","en":"\"哪儿都没去\" = didn't go anywhere, matching \"stayed in the office\"."}},{"q":"面试的时候别紧张，你知道什么就说____。","options":["哪儿","什么","谁","怎么"],"answer":1,"explain":{"vi":"\"知道什么就说什么\" = biết gì nói nấy.","en":"\"知道什么就说什么\" = say whatever you know."}}]},
  {"id":"g22","title":{"zh":"反问句","vi":"Câu hỏi tu từ (phản vấn)","en":"Rhetorical questions"},"pattern":"难道…吗? ; 不是…吗? ; 怎么能…呢? ; 哪儿…啊?","explain":{"vi":"Câu hỏi tu từ không cần trả lời, dùng để nhấn mạnh ý ngược lại: câu khẳng định mang nghĩa phủ định và ngược lại. Bẫy hay gặp: 难道 và 不是 đi với 吗, còn 怎么能 đi với 呢; \"我哪儿有时间\" nghĩa là \"tôi không có thời gian\".","en":"A rhetorical question expects no answer and stresses the opposite meaning: a positive form means negative and vice versa. Common trap: 难道 and 不是 end with 吗, while 怎么能 ends with 呢; \"我哪儿有时间\" means \"I have no time\"."},"examples":[{"zh":"难道你不知道明天要开会吗？","py":"Nándào nǐ bù zhīdào míngtiān yào kāihuì ma?","vi":"Chẳng lẽ bạn không biết mai phải họp à?","en":"Don't you know there's a meeting tomorrow?"},{"zh":"这不是上个月的工资表吗？","py":"Zhè bú shì shàng ge yuè de gōngzī biǎo ma?","vi":"Đây chẳng phải là bảng lương tháng trước sao?","en":"Isn't this last month's payroll sheet?"}],"quiz":[{"q":"____你忘了今天下午的面试吗？","options":["为什么","难道","怎么","哪儿"],"answer":1,"explain":{"vi":"\"难道…吗\" là mẫu câu hỏi tu từ tỏ ý ngạc nhiên.","en":"\"难道…吗\" is the rhetorical pattern showing surprise."}},{"q":"他是经理，这件事他怎么能不知道____？","options":["吗","了","过","呢"],"answer":3,"explain":{"vi":"\"怎么能…呢\" là cặp cố định trong câu hỏi tu từ.","en":"\"怎么能…呢\" is a fixed rhetorical pair."}},{"q":"\"我哪儿有时间啊？\"的意思是：","options":["我没有时间。","我有很多时间。","我在找时间。","我不知道时间。"],"answer":0,"explain":{"vi":"\"哪儿有…啊\" mang nghĩa phủ định: không có.","en":"\"哪儿有…啊\" has a negative meaning: there is none."}},{"q":"这份合同你不是已经签了____？","options":["着","过","吗","得"],"answer":2,"explain":{"vi":"\"不是…吗\" dùng để nhấn mạnh điều người nói cho là đúng.","en":"\"不是…吗\" stresses what the speaker believes is true."}},{"q":"下面哪个句子是对的？","options":["难道你不想加工资吗？","难道你不想加工资呢？","你难道不想加工资吧？","难道你不想加工资了没有？"],"answer":0,"explain":{"vi":"难道 phải kết thúc bằng 吗.","en":"难道 must end with 吗."}}]},
  {"id":"g23","title":{"zh":"动态助词 着/了/过","vi":"Trợ từ động thái 着/了/过","en":"Aspect particles 着 / 了 / 过"},"pattern":"V着 (trạng thái/ongoing) ; V了 (hoàn thành/completed) ; V过 (kinh nghiệm/experience), 没V过","explain":{"vi":"着 chỉ trạng thái đang duy trì, 了 chỉ hành động đã hoàn thành, 过 chỉ kinh nghiệm từng làm. Bẫy hay gặp: phủ định của 了 là \"没V\" (bỏ 了), còn phủ định của 过 là \"没V过\" (giữ 过).","en":"着 marks a continuing state, 了 a completed action, and 过 a past experience. Common trap: the negative of 了 is \"没V\" (drop 了), but the negative of 过 is \"没V过\" (keep 过)."},"examples":[{"zh":"会议室的门开着，里面没有人。","py":"Huìyìshì de mén kāi zhe, lǐmiàn méiyǒu rén.","vi":"Cửa phòng họp đang mở, bên trong không có ai.","en":"The meeting room door is open, but nobody is inside."},{"zh":"我以前在一家外国公司工作过。","py":"Wǒ yǐqián zài yì jiā wàiguó gōngsī gōngzuò guo.","vi":"Trước đây tôi từng làm ở một công ty nước ngoài.","en":"I used to work at a foreign company."}],"quiz":[{"q":"我从来没去____北京。","options":["着","了","过","的"],"answer":2,"explain":{"vi":"\"从来没V过\" diễn tả chưa từng có kinh nghiệm.","en":"\"从来没V过\" expresses never having had the experience."}},{"q":"他笑____对我说：\"欢迎你来我们公司！\"","options":["着","了","过","得"],"answer":0,"explain":{"vi":"\"V1着V2\" chỉ cách thức làm hành động thứ hai.","en":"\"V1着V2\" shows the manner of the second action."}},{"q":"我昨天已经把报告交给经理____。","options":["着","过","呢","了"],"answer":3,"explain":{"vi":"\"已经…了\" chỉ hành động đã hoàn thành.","en":"\"已经…了\" marks a completed action."}},{"q":"你先在这儿坐____，经理马上就来。","options":["了","着","过","得"],"answer":1,"explain":{"vi":"\"坐着\" chỉ duy trì trạng thái ngồi chờ.","en":"\"坐着\" means to stay seated and wait."}},{"q":"下面哪个句子是对的？","options":["我没看了这份材料。","我不看过这份材料。","我没看过这份材料。","我没看这份材料过。"],"answer":2,"explain":{"vi":"Phủ định kinh nghiệm là \"没V过\", 过 đứng ngay sau động từ.","en":"The negative experience form is \"没V过\", with 过 right after the verb."}}]},
  {"id":"g24","title":{"zh":"一边……一边 / 先……然后(再) / 一……就","vi":"Hành động đồng thời và nối tiếp","en":"Simultaneous and sequential actions"},"pattern":"一边 V1, 一边 V2 ; 先 V1, 然后(再) V2 ; 一 V1 就 V2","explain":{"vi":"\"一边…一边\" chỉ hai hành động xảy ra cùng lúc; \"先…然后/再\" chỉ thứ tự trước sau; \"一…就\" nghĩa là \"vừa… là…\" ngay lập tức. Bẫy hay gặp: không trộn cặp (一边…然后, 一…然后 đều sai), và 就 phải đứng sau chủ ngữ vế sau.","en":"\"一边…一边\" is for two actions at the same time; \"先…然后/再\" gives the order; \"一…就\" means \"as soon as\". Common trap: don't mix the pairs (一边…然后 or 一…然后 are wrong), and 就 goes after the second subject."},"examples":[{"zh":"她一边听电话，一边记笔记。","py":"Tā yìbiān tīng diànhuà, yìbiān jì bǐjì.","vi":"Cô ấy vừa nghe điện thoại vừa ghi chép.","en":"She takes notes while on the phone."},{"zh":"我们先看简历，然后再安排面试。","py":"Wǒmen xiān kàn jiǎnlì, ránhòu zài ānpái miànshì.","vi":"Chúng ta xem hồ sơ trước, sau đó mới sắp xếp phỏng vấn.","en":"We'll review the CVs first and then schedule interviews."}],"quiz":[{"q":"他____到公司，就开始工作了。","options":["一","先","边","再"],"answer":0,"explain":{"vi":"\"一…就\" = vừa đến là bắt đầu làm ngay.","en":"\"一…就\" = started work as soon as he arrived."}},{"q":"我们先吃饭，____去开会吧。","options":["一边","然后","一","着"],"answer":1,"explain":{"vi":"\"先…然后\" chỉ thứ tự hai hành động.","en":"\"先…然后\" gives the order of two actions."}},{"q":"她喜欢一边听音乐，____工作。","options":["然后","就","一边","先"],"answer":2,"explain":{"vi":"\"一边…一边\" phải dùng thành cặp.","en":"\"一边…一边\" must be used as a pair."}},{"q":"小王一看到那封邮件，____给客户打了电话。","options":["才","再","也","就"],"answer":3,"explain":{"vi":"\"一…就\" chỉ hành động xảy ra ngay sau đó.","en":"\"一…就\" shows the action followed immediately."}},{"q":"下面哪个句子是对的？","options":["你一边填这张表，然后交给我。","你先填这张表，然后交给我。","你先填这张表，一边交给我。","你一填这张表，然后交给我。"],"answer":1,"explain":{"vi":"Chỉ \"先…然后\" là cặp đúng; các câu khác trộn sai cặp.","en":"Only \"先…然后\" is a correct pair; the others mix pairs."}}]},
  {"id":"g25","title":{"zh":"关联词 于是/然而/而/甚至/并且","vi":"Liên từ 于是/然而/而/甚至/并且","en":"Linking words 于是 / 然而 / 而 / 甚至 / 并且"},"pattern":"A，于是 B (kết quả/so) ; A，然而 B (chuyển ý/however) ; A，而 B (đối lập/whereas) ; A，甚至 B (thậm chí/even) ; A，并且 B (và còn/and also)","explain":{"vi":"于是 nối hành động xảy ra do tình huống trước; 然而 chỉ sự chuyển ý trái kỳ vọng; 而 so sánh hai sự việc đối lập; 甚至 nêu mức độ cao hơn; 并且 bổ sung thêm ý. Bẫy hay gặp: 于是 chỉ dùng cho việc đã xảy ra, không dùng cho mệnh lệnh hay tương lai.","en":"于是 links an action that followed from the situation; 然而 marks an unexpected turn; 而 contrasts two facts; 甚至 adds a stronger point; 并且 adds another point. Common trap: 于是 is only for things that already happened, not for requests or future plans."},"examples":[{"zh":"他工作很认真，并且经常帮助同事。","py":"Tā gōngzuò hěn rènzhēn, bìngqiě jīngcháng bāngzhù tóngshì.","vi":"Anh ấy làm việc rất chăm chỉ, và còn thường giúp đỡ đồng nghiệp.","en":"He works hard and also often helps his colleagues."},{"zh":"大家都很努力，然而任务还没完成。","py":"Dàjiā dōu hěn nǔlì, rán'ér rènwù hái méi wánchéng.","vi":"Mọi người đều rất cố gắng, nhưng nhiệm vụ vẫn chưa xong.","en":"Everyone worked hard; however, the task isn't finished yet."}],"quiz":[{"q":"我等了半个小时他还没来，____我就先走了。","options":["然而","甚至","于是","并且"],"answer":2,"explain":{"vi":"于是 chỉ hành động xảy ra do tình huống trước đó.","en":"于是 introduces an action caused by the previous situation."}},{"q":"这次招聘我们准备了很长时间，____结果并不理想。","options":["然而","于是","甚至","并且"],"answer":0,"explain":{"vi":"然而 chỉ kết quả trái với kỳ vọng.","en":"然而 marks a result contrary to expectation."}},{"q":"他的汉语非常好，____能用中文写合同。","options":["于是","然而","而","甚至"],"answer":3,"explain":{"vi":"甚至 nêu ra một mức độ cao hơn để nhấn mạnh.","en":"甚至 adds a stronger point for emphasis."}},{"q":"请大家认真填写这张表，____在周五以前交给人事部。","options":["甚至","并且","然而","于是"],"answer":1,"explain":{"vi":"并且 bổ sung thêm một yêu cầu nữa.","en":"并且 adds one more requirement."}},{"q":"南方已经很热了，____北方还很冷。","options":["而","于是","并且","甚至"],"answer":0,"explain":{"vi":"而 dùng để đối lập hai sự việc.","en":"而 contrasts two facts."}}]},
  {"id":"g26","title":{"zh":"不是……而是","vi":"Không phải… mà là","en":"不是…而是 (not A but B)"},"pattern":"不是 + A，而是 + B","explain":{"vi":"Dùng để phủ định ý A rồi nêu ý đúng là B. Hai vế phải cùng loại (cùng là danh từ, động từ hoặc mệnh đề). Lỗi hay gặp: dịch \"mà là\" thành 但是; vế sau phải dùng 而是.","en":"Use it to reject A and state the correct fact B. Both halves must be the same kind of phrase. Common mistake: using 但是 for the second half; it must be 而是."},"examples":[{"zh":"我不是不想去，而是真的没有时间。","py":"Wǒ bú shì bù xiǎng qù, ér shì zhēn de méiyǒu shíjiān.","vi":"Không phải tôi không muốn đi, mà là thật sự không có thời gian.","en":"It's not that I don't want to go; I really have no time."},{"zh":"这不是他一个人的责任，而是大家的责任。","py":"Zhè bú shì tā yí ge rén de zérèn, ér shì dàjiā de zérèn.","vi":"Đây không phải trách nhiệm của riêng anh ấy, mà là của mọi người.","en":"This is not his responsibility alone but everyone's."}],"quiz":[{"q":"我们现在需要的不是更多的钱，____更多的时间。","options":["但是","而是","而且","或者"],"answer":1,"explain":{"vi":"Vế trước phủ định bằng 不是, vế sau nêu ý đúng phải dùng 而是.","en":"After 不是 rejects one thing, 而是 introduces the correct one."}},{"q":"他迟到不是因为起晚了，____因为路上堵车。","options":["所以","于是","还是","而是"],"answer":3,"explain":{"vi":"Cấu trúc 不是因为…而是因为…: không phải vì A mà là vì B.","en":"不是因为…而是因为… means \"not because of A but because of B\"."}},{"q":"下面哪个句子是正确的？","options":["这不是我的手机，而是小李的。","这不是我的手机，但是小李的。","这而是小李的手机，不是我的。","这不是我的手机，而小李的是。"],"answer":0,"explain":{"vi":"而是 đứng đầu vế sau, ngay sau vế 不是.","en":"而是 opens the second half, right after the 不是 clause."}},{"q":"问题____出在计划上，而是出在管理上。","options":["不要","不但","不是","不管"],"answer":2,"explain":{"vi":"Vế sau có 而是 nên vế trước phải là 不是.","en":"The second half has 而是, so the first half needs 不是."}},{"q":"我说的不是这个星期五，而是____。","options":["去参加","下个星期五","很重要","没有时间"],"answer":1,"explain":{"vi":"Hai vế phải cùng loại: 这个星期五 đi với 下个星期五.","en":"Both halves must match in type: 这个星期五 pairs with 下个星期五."}}]},
  {"id":"g27","title":{"zh":"不是……就是","vi":"Không… thì…","en":"不是…就是 (either A or B)"},"pattern":"不是 + A，就是 + B","explain":{"vi":"Chỉ có hai khả năng: không phải A thì là B. Thường dùng để tả thói quen hoặc phỏng đoán. Lỗi hay gặp: nhầm với 不是…而是 (phủ định A, khẳng định B); ở đây cả A và B đều có thể đúng.","en":"Only two possibilities exist: if it is not A, it is B. Often used for habits or guesses. Common mistake: confusing it with 不是…而是 (A is rejected, B is true); here either A or B may be true."},"examples":[{"zh":"他周末不是加班，就是在家睡觉。","py":"Tā zhōumò bú shì jiābān, jiù shì zài jiā shuìjiào.","vi":"Cuối tuần anh ấy không tăng ca thì ngủ ở nhà.","en":"On weekends he is either working overtime or sleeping at home."},{"zh":"这个时间他不是在开会，就是在见客人。","py":"Zhège shíjiān tā bú shì zài kāihuì, jiù shì zài jiàn kèrén.","vi":"Giờ này anh ấy không họp thì đang tiếp khách.","en":"At this hour he is either in a meeting or seeing a visitor."}],"quiz":[{"q":"这个星期每天不是刮风，____下雨，没有一天是晴天。","options":["还是","但是","就是","所以"],"answer":2,"explain":{"vi":"不是…就是: mỗi ngày không gió thì mưa.","en":"不是…就是: each day it was either windy or rainy."}},{"q":"“他不是在办公室，就是在会议室”的意思是：","options":["他不在办公室，在会议室","他在办公室或者在会议室","他不在办公室，也不在会议室","他在办公室，也在会议室"],"answer":1,"explain":{"vi":"不是…就是 nêu hai khả năng, một trong hai là đúng.","en":"不是…就是 gives two possibilities, one of which is true."}},{"q":"她每天中午____吃面条，就是吃米饭。","options":["不是","不但","虽然","只有"],"answer":0,"explain":{"vi":"Vế sau có 就是 nên vế trước dùng 不是.","en":"The second half has 就是, so the first half takes 不是."}},{"q":"下面哪个句子是正确的？","options":["他不是打电话，就是邮件发。","他不打电话是，就是发邮件。","他不是打电话，是就发邮件。","他不是打电话，就是发邮件。"],"answer":3,"explain":{"vi":"Sau 不是 và 就是 là hai cụm động từ có cấu trúc giống nhau.","en":"不是 and 就是 are each followed by a verb phrase of the same form."}},{"q":"这件事不是你告诉他的，就是小王告诉他的，没有____知道。","options":["大家","别人","我们","你们"],"answer":1,"explain":{"vi":"Chỉ có hai khả năng (你 hoặc 小王), nên không có ai khác biết.","en":"Only two people are possible, so nobody else knows."}}]},
  {"id":"g28","title":{"zh":"与其……不如","vi":"Thà… còn hơn…","en":"与其…不如 (rather than A, better B)"},"pattern":"与其 + A，不如 + B  (B is preferred)","explain":{"vi":"So sánh hai cách làm và chọn B: \"làm A thì chẳng bằng làm B\". Lỗi hay gặp: đặt điều mình chọn sau 与其; điều được chọn luôn đứng sau 不如.","en":"Compares two choices and prefers B: \"rather than A, it is better to B\". Common mistake: putting the preferred choice after 与其; the preferred one always follows 不如."},"examples":[{"zh":"与其在这儿等，不如我们自己去找他。","py":"Yǔqí zài zhèr děng, bùrú wǒmen zìjǐ qù zhǎo tā.","vi":"Thà chúng ta tự đi tìm anh ấy còn hơn đợi ở đây.","en":"Rather than wait here, we had better go and find him ourselves."},{"zh":"与其每天加班，不如想办法节约时间。","py":"Yǔqí měi tiān jiābān, bùrú xiǎng bànfǎ jiéyuē shíjiān.","vi":"Thay vì ngày nào cũng tăng ca, chi bằng nghĩ cách tiết kiệm thời gian.","en":"Rather than work overtime every day, it is better to find ways to save time."}],"quiz":[{"q":"与其坐在这儿担心，____现在就开始准备。","options":["而是","就是","而且","不如"],"answer":3,"explain":{"vi":"与其 đi với 不如.","en":"与其 pairs with 不如."}},{"q":"____花很多钱买新的，不如把旧的修一修。","options":["尽管","与其","因为","不管"],"answer":1,"explain":{"vi":"Vế sau có 不如 nên vế trước dùng 与其.","en":"The second half has 不如, so the first half takes 与其."}},{"q":"“与其打车，不如坐地铁”，说话人觉得应该：","options":["打车","走路","坐地铁","什么车都不坐"],"answer":2,"explain":{"vi":"Điều được chọn đứng sau 不如.","en":"The preferred choice comes after 不如."}},{"q":"下面哪个句子是正确的？","options":["与其明天做，不如今天做完。","不如明天做，与其今天做完。","与其明天做，而是今天做完。","与其明天做不如，今天做完。"],"answer":0,"explain":{"vi":"与其 đứng đầu vế trước, 不如 đứng đầu vế sau.","en":"与其 opens the first half and 不如 opens the second."}},{"q":"与其让他一个人负责，不如____。","options":["他很累","大家一起负责","一个人负责","没有人知道"],"answer":1,"explain":{"vi":"Sau 不如 là cách làm tốt hơn, cùng loại với vế trước.","en":"不如 is followed by the better way of doing it, parallel to the first half."}}]},
  {"id":"g29","title":{"zh":"之所以……是因为","vi":"Sở dĩ… là vì…","en":"之所以…是因为 (the reason why… is that…)"},"pattern":"S + 之所以 + result，是因为 + reason","explain":{"vi":"Nêu kết quả trước rồi nhấn mạnh nguyên nhân ở vế sau. 之所以 đứng sau chủ ngữ. Lỗi hay gặp: vế sau dùng 所以/因此 hoặc bỏ 是; vế sau phải là 是因为.","en":"States the result first, then stresses the reason. 之所以 comes after the subject. Common mistake: using 所以/因此 or dropping 是 in the second half; it must be 是因为."},"examples":[{"zh":"他之所以成功，是因为一直很努力。","py":"Tā zhīsuǒyǐ chénggōng, shì yīnwèi yìzhí hěn nǔlì.","vi":"Sở dĩ anh ấy thành công là vì luôn rất cố gắng.","en":"The reason he succeeded is that he has always worked hard."},{"zh":"我之所以选择这家公司，是因为环境很好。","py":"Wǒ zhīsuǒyǐ xuǎnzé zhè jiā gōngsī, shì yīnwèi huánjìng hěn hǎo.","vi":"Sở dĩ tôi chọn công ty này là vì môi trường rất tốt.","en":"The reason I chose this company is that the environment is good."}],"quiz":[{"q":"她之所以没来上班，____孩子生病了。","options":["所以","是因为","于是","因此"],"answer":1,"explain":{"vi":"之所以 đi với 是因为 để nêu nguyên nhân.","en":"之所以 pairs with 是因为 to give the reason."}},{"q":"我____同意这个计划，是因为它能节约时间。","options":["因为","由于","之所以","既然"],"answer":2,"explain":{"vi":"Vế sau là 是因为 (nguyên nhân), nên vế trước nêu kết quả với 之所以.","en":"The second half gives the reason with 是因为, so the first half states the result with 之所以."}},{"q":"“他之所以迟到，是因为堵车”，他迟到的原因是：","options":["堵车","迟到","上班","起晚了"],"answer":0,"explain":{"vi":"Nguyên nhân đứng sau 是因为.","en":"The reason follows 是因为."}},{"q":"下面哪个句子是正确的？","options":["之所以大家喜欢她，所以她很热情。","大家喜欢她之所以，是因为她很热情。","大家之所以喜欢她，因此她很热情。","大家之所以喜欢她，是因为她很热情。"],"answer":3,"explain":{"vi":"之所以 đứng sau chủ ngữ, vế sau bắt đầu bằng 是因为.","en":"之所以 follows the subject and the second half starts with 是因为."}},{"q":"这次活动之所以顺利，是因为____。","options":["活动很顺利","所以很成功","大家准备得很认真","顺利地结束"],"answer":2,"explain":{"vi":"Sau 是因为 phải là nguyên nhân dẫn đến kết quả.","en":"是因为 must be followed by the cause of the result."}}]},
  {"id":"g30","title":{"zh":"既……又/也","vi":"Vừa… vừa…","en":"既…又/也 (both… and…)"},"pattern":"S + 既 + Adj/V1 + 又/也 + Adj/V2","explain":{"vi":"Một chủ thể có cùng lúc hai tính chất hoặc hai hành động: \"vừa… vừa…\". 既 đứng sau chủ ngữ; hai vế phải cùng hướng nghĩa (cùng tốt hoặc cùng xấu). Lỗi hay gặp: nhầm 既 với 既然 (đã… thì).","en":"One subject has two qualities or does two things: \"both… and…\". 既 follows the subject and both parts point the same way (both good or both bad). Common mistake: confusing 既 with 既然 (since)."},"examples":[{"zh":"这个办法既简单又安全。","py":"Zhège bànfǎ jì jiǎndān yòu ānquán.","vi":"Cách này vừa đơn giản vừa an toàn.","en":"This method is both simple and safe."},{"zh":"她既是我的同事，也是我的好朋友。","py":"Tā jì shì wǒ de tóngshì, yě shì wǒ de hǎo péngyou.","vi":"Cô ấy vừa là đồng nghiệp, vừa là bạn tốt của tôi.","en":"She is both my colleague and my good friend."}],"quiz":[{"q":"新来的同事既聪明____有礼貌。","options":["就","才","又","却"],"answer":2,"explain":{"vi":"既…又… nối hai tính chất cùng tốt.","en":"既…又… links two qualities of the same kind."}},{"q":"他____会说汉语，也会说日语。","options":["既","既然","即使","无论"],"answer":0,"explain":{"vi":"既…也…: vừa biết tiếng Trung vừa biết tiếng Nhật; 既然 nghĩa là \"đã… thì\".","en":"既…也…: he speaks both; 既然 means \"since\"."}},{"q":"这家饭馆的菜既便宜又____。","options":["难吃","太贵","很少","好吃"],"answer":3,"explain":{"vi":"Hai tính chất phải cùng hướng: 便宜 (tốt) đi với 好吃 (tốt).","en":"Both qualities must point the same way: cheap goes with tasty."}},{"q":"下面哪个句子是正确的？","options":["这份工作既轻松就有意思。","这份工作既轻松又有意思。","既这份工作轻松又有意思。","这份工作又轻松既有意思。"],"answer":1,"explain":{"vi":"既 đứng sau chủ ngữ và đứng trước 又.","en":"既 follows the subject and comes before 又."}},{"q":"做这个工作既要有经验，____要有耐心。","options":["而","才","就","也"],"answer":3,"explain":{"vi":"既要…也要…: vừa cần… vừa cần….","en":"既要…也要…: it requires both."}}]},
  {"id":"g31","title":{"zh":"一方面……另一方面","vi":"Một mặt… mặt khác…","en":"一方面…另一方面 (on the one hand… on the other…)"},"pattern":"一方面 + A，另一方面 + (也/又/还) + B","explain":{"vi":"Nêu hai mặt của một vấn đề hoặc hai lý do song song. Lỗi hay gặp: dùng cho hai hành động làm cùng một lúc; trường hợp đó phải dùng 一边…一边.","en":"Gives two sides of one matter or two parallel reasons. Common mistake: using it for two actions done at the same moment; that needs 一边…一边."},"examples":[{"zh":"我学汉语一方面是兴趣，另一方面是工作需要。","py":"Wǒ xué Hànyǔ yì fāngmiàn shì xìngqù, lìng yì fāngmiàn shì gōngzuò xūyào.","vi":"Tôi học tiếng Trung một mặt vì sở thích, mặt khác vì công việc cần.","en":"I study Chinese partly out of interest and partly because my job needs it."},{"zh":"一方面要保证质量，另一方面也要注意速度。","py":"Yì fāngmiàn yào bǎozhèng zhìliàng, lìng yì fāngmiàn yě yào zhùyì sùdù.","vi":"Một mặt phải đảm bảo chất lượng, mặt khác cũng phải chú ý tốc độ.","en":"On the one hand we must guarantee quality; on the other we must watch the speed."}],"quiz":[{"q":"他换工作，一方面是因为工资低，____是因为离家太远。","options":["一边","而是","另一方面","于是"],"answer":2,"explain":{"vi":"Hai lý do song song: 一方面…另一方面….","en":"Two parallel reasons: 一方面…另一方面…."}},{"q":"她____听音乐，一边打扫房间。","options":["一方面","一边","另一方面","既然"],"answer":1,"explain":{"vi":"Hai hành động làm cùng lúc dùng 一边…一边.","en":"Two actions done at the same time take 一边…一边."}},{"q":"我们一方面要加快速度，另一方面____要保证质量。","options":["也","才","倒","刚"],"answer":0,"explain":{"vi":"Sau 另一方面 thường có 也/又/还.","en":"另一方面 is usually followed by 也/又/还."}},{"q":"下面哪个句子是正确的？","options":["这次旅行一方面可以休息，一边可以了解中国文化。","这次旅行另一方面可以休息，一方面可以了解中国文化。","一方面这次旅行可以休息，另一边可以了解中国文化。","这次旅行一方面可以休息，另一方面可以了解中国文化。"],"answer":3,"explain":{"vi":"一方面 ở vế trước, 另一方面 ở vế sau.","en":"一方面 goes in the first half and 另一方面 in the second."}},{"q":"“一方面……另一方面”用来说明：","options":["两个动作一起进行","一件事情的两个方面","在两个里面选一个","事情发生的先后"],"answer":1,"explain":{"vi":"Cấu trúc này nêu hai mặt của cùng một vấn đề.","en":"This pattern presents two sides of the same matter."}}]},
  {"id":"g32","title":{"zh":"对于 / 关于 / 至于","vi":"Giới từ 对于 / 关于 / 至于","en":"对于 / 关于 / 至于 (towards / about / as for)"},"pattern":"对于 + O，S + V  /  S + 对于 + O + V | 关于 + topic，…  /  关于 + topic + 的 + N | A…，至于 + B，…","explain":{"vi":"对于 chỉ đối tượng của thái độ, đánh giá, đứng trước hoặc sau chủ ngữ. 关于 chỉ nội dung, phạm vi liên quan, chỉ đứng đầu câu hoặc làm định ngữ (关于…的…). 至于 chuyển sang một chủ đề khác. Lỗi hay gặp: đặt 关于 sau chủ ngữ (我关于这件事… là sai).","en":"对于 marks the target of an attitude or judgement and can go before or after the subject. 关于 marks the content or scope; it only opens the sentence or modifies a noun (关于…的…). 至于 switches to another topic. Common mistake: putting 关于 after the subject."},"examples":[{"zh":"关于放假的安排，人事部明天会通知大家。","py":"Guānyú fàngjià de ānpái, rénshìbù míngtiān huì tōngzhī dàjiā.","vi":"Về lịch nghỉ, phòng nhân sự sẽ thông báo cho mọi người vào ngày mai.","en":"As for the holiday schedule, HR will notify everyone tomorrow."},{"zh":"对于这个问题，我们的看法不太一样。","py":"Duìyú zhège wèntí, wǒmen de kànfǎ bú tài yíyàng.","vi":"Đối với vấn đề này, quan điểm của chúng tôi không giống nhau lắm.","en":"On this issue our views are not quite the same."}],"quiz":[{"q":"我想买一本____中国历史的书。","options":["对于","至于","关于","由于"],"answer":2,"explain":{"vi":"Làm định ngữ chỉ nội dung của sách phải dùng 关于…的.","en":"To describe a book's content as a modifier, use 关于…的."}},{"q":"我只知道他要离开公司，____他去哪儿，我不清楚。","options":["由于","至于","甚至","终于"],"answer":1,"explain":{"vi":"至于 dùng để chuyển sang một chủ đề khác có liên quan.","en":"至于 switches to another related topic."}},{"q":"我们____这个计划很有信心。","options":["关于","至于","由于","对于"],"answer":3,"explain":{"vi":"Sau chủ ngữ, chỉ đối tượng của thái độ (有信心) dùng 对于; 关于 không đứng sau chủ ngữ.","en":"After the subject, the target of an attitude takes 对于; 关于 cannot follow the subject."}},{"q":"下面哪个句子是正确的？","options":["我关于这件事没有意见。","关于工资的问题，请问人事部。","至于这本书是历史的。","这是一本对于经济的杂志。"],"answer":1,"explain":{"vi":"关于 đứng đầu câu để nêu chủ đề; 对于 không dùng để chỉ nội dung sách báo.","en":"关于 opens the sentence to set the topic; 对于 cannot describe the content of a publication."}},{"q":"____年轻人来说，积累经验比赚钱更重要。","options":["对于","关于","至于","按照"],"answer":0,"explain":{"vi":"对于…来说: đối với… mà nói.","en":"对于…来说 means \"as far as … is concerned\"."}}]},
  {"id":"g33","title":{"zh":"根据 / 按照","vi":"Giới từ 根据 / 按照","en":"根据 / 按照 (based on / according to)"},"pattern":"根据 + basis，+ judgement or decision | 按照 + rule / plan / requirement + V | 有 / 没有 + 根据","explain":{"vi":"根据: dựa vào thông tin, số liệu, tình hình để phán đoán hay quyết định; còn là danh từ \"căn cứ\". 按照: làm đúng theo quy định, kế hoạch, yêu cầu, thứ tự. Lỗi hay gặp: dùng 按照 làm danh từ (有什么按照 là sai).","en":"根据: judging or deciding on the basis of information or a situation; it is also a noun, \"basis\". 按照: doing something as a rule, plan, requirement or order says. Common mistake: using 按照 as a noun."},"examples":[{"zh":"根据调查结果，大部分顾客比较满意。","py":"Gēnjù diàochá jiéguǒ, dàbùfen gùkè bǐjiào mǎnyì.","vi":"Theo kết quả điều tra, phần lớn khách hàng khá hài lòng.","en":"According to the survey results, most customers are fairly satisfied."},{"zh":"请按照公司的规定填写这张表格。","py":"Qǐng ànzhào gōngsī de guīdìng tiánxiě zhè zhāng biǎogé.","vi":"Vui lòng điền bảng này theo quy định của công ty.","en":"Please fill in this form according to company rules."}],"quiz":[{"q":"请大家____顺序排队，不要着急。","options":["关于","由于","按照","对于"],"answer":2,"explain":{"vi":"Làm theo thứ tự dùng 按照.","en":"Following an order takes 按照."}},{"q":"____天气预报，明天会下大雨。","options":["为了","根据","对于","向"],"answer":1,"explain":{"vi":"Dựa vào thông tin để phán đoán dùng 根据.","en":"Judging from information takes 根据."}},{"q":"你就____我说的方法做吧，不会错的。","options":["按照","关于","至于","随着"],"answer":0,"explain":{"vi":"Làm đúng theo một cách thức đã cho dùng 按照.","en":"Doing something the way you were told takes 按照."}},{"q":"你说他不负责任，有什么____吗？","options":["按照","关于","对于","根据"],"answer":3,"explain":{"vi":"Chỉ 根据 mới dùng được như danh từ (\"căn cứ\").","en":"Only 根据 can be a noun meaning \"basis\"."}},{"q":"下面哪个句子是正确的？","options":["我们会计划按照完成任务。","我们按照会计划完成任务。","我们会按照计划完成任务。","按照我们会完成任务计划。"],"answer":2,"explain":{"vi":"按照 + danh từ đứng trước động từ, sau trợ động từ 会.","en":"按照 + noun goes before the verb and after the modal 会."}}]},
  {"id":"g34","title":{"zh":"随着","vi":"Giới từ 随着 (cùng với)","en":"随着 (along with, as)"},"pattern":"随着 + N + 的 + change (发展 / 提高 / 增加 / 变化)，S + 也 / 越来越…","explain":{"vi":"Diễn tả B thay đổi theo sự thay đổi của A. Sau 随着 phải là một sự thay đổi (发展, 提高, 增加, 变化…), vế sau nêu kết quả thay đổi theo. Lỗi hay gặp: sau 随着 chỉ có danh từ tĩnh (随着经济，… là sai, phải nói 随着经济的发展).","en":"Says that B changes as A changes. 随着 must be followed by a change (发展, 提高, 增加, 变化…), and the main clause gives what changes with it. Common mistake: a bare static noun after 随着 (随着经济，… is wrong; say 随着经济的发展)."},"examples":[{"zh":"随着经济的发展，人们的收入越来越高。","py":"Suízhe jīngjì de fāzhǎn, rénmen de shōurù yuè lái yuè gāo.","vi":"Cùng với sự phát triển kinh tế, thu nhập của mọi người ngày càng cao.","en":"As the economy develops, people's incomes keep rising."},{"zh":"随着年龄的增加，他变得更有耐心了。","py":"Suízhe niánlíng de zēngjiā, tā biàn de gèng yǒu nàixīn le.","vi":"Càng lớn tuổi, anh ấy càng trở nên kiên nhẫn hơn.","en":"As he gets older, he has become more patient."}],"quiz":[{"q":"____技术的发展，我们的生活方便多了。","options":["按照","随着","关于","为了"],"answer":1,"explain":{"vi":"B thay đổi theo sự phát triển của A dùng 随着.","en":"B changing along with A's development takes 随着."}},{"q":"随着天气变冷，感冒的人____。","options":["已经来了","一共三个","越来越多","很少去过"],"answer":2,"explain":{"vi":"Vế sau 随着 nêu sự thay đổi, thường có 越来越.","en":"The clause after 随着 states a change, often with 越来越."}},{"q":"随着经验的____，她的工作能力提高了很多。","options":["积累","已经","安排","经历"],"answer":0,"explain":{"vi":"随着 + danh từ + 的 + từ chỉ sự thay đổi (积累).","en":"随着 + noun + 的 + a word of change (积累)."}},{"q":"下面哪个句子是正确的？","options":["人数随着的增加，办公室不够用了。","随着办公室不够用了，人数的增加。","随着了人数增加，办公室不够用。","随着人数的增加，办公室不够用了。"],"answer":3,"explain":{"vi":"随着 đứng đầu câu, sau nó là \"danh từ + 的 + sự thay đổi\".","en":"随着 opens the sentence, followed by \"noun + 的 + change\"."}},{"q":"随着公司的发展，____。","options":["我昨天请假了","需要的人越来越多","他是经理","办公室在三楼"],"answer":1,"explain":{"vi":"Vế sau phải là điều thay đổi theo sự phát triển của công ty.","en":"The main clause must be something that changes as the company grows."}}]},
  {"id":"g35","title":{"zh":"通过 / 经过","vi":"通过 / 经过 (thông qua / trải qua)","en":"通过 / 经过 (by means of / after going through)"},"pattern":"通过 + method / person，+ result | 通过 + 考试 / 检查 (pass) | 经过 + process / period，+ result | 经过 + place","explain":{"vi":"通过 nhấn mạnh phương tiện, cách thức hoặc người trung gian; còn có nghĩa \"thi đỗ, được thông qua\". 经过 nhấn mạnh đã trải qua một quá trình, một khoảng thời gian, hoặc đi ngang qua một nơi. Lỗi hay gặp: nói 经过考试 với nghĩa \"thi đỗ\" (phải là 通过考试).","en":"通过 stresses the means, method or go-between; it also means \"to pass\" (an exam, a check). 经过 stresses having gone through a process or period, or passing by a place. Common mistake: 经过考试 for \"pass the exam\" (it must be 通过考试)."},"examples":[{"zh":"通过这次交流，我们互相了解了很多。","py":"Tōngguò zhè cì jiāoliú, wǒmen hùxiāng liǎojiě le hěn duō.","vi":"Qua lần trao đổi này, chúng tôi hiểu nhau hơn rất nhiều.","en":"Through this exchange we got to know each other much better."},{"zh":"经过三个月的努力，他终于通过了考试。","py":"Jīngguò sān ge yuè de nǔlì, tā zhōngyú tōngguò le kǎoshì.","vi":"Sau ba tháng cố gắng, cuối cùng anh ấy đã thi đỗ.","en":"After three months of hard work, he finally passed the exam."}],"quiz":[{"q":"他是____朋友介绍找到这份工作的。","options":["根据","按照","随着","通过"],"answer":3,"explain":{"vi":"Nhờ người trung gian để đạt kết quả dùng 通过.","en":"Getting a result by way of a go-between takes 通过."}},{"q":"我每天上班都要____那家银行。","options":["通过","经过","根据","对于"],"answer":1,"explain":{"vi":"Đi ngang qua một địa điểm dùng 经过.","en":"Passing by a place takes 经过."}},{"q":"祝贺你____了这次汉语水平考试！","options":["经过","根据","通过","按照"],"answer":2,"explain":{"vi":"\"Thi đỗ\" là 通过考试.","en":"\"To pass an exam\" is 通过考试."}},{"q":"____一年的学习，她的汉语已经很流利了。","options":["经过","根据","按照","关于"],"answer":0,"explain":{"vi":"Trải qua một khoảng thời gian, một quá trình dùng 经过.","en":"Going through a period or process takes 经过."}},{"q":"下面哪个句子是正确的？","options":["这次活动通过，大家认识了很多新朋友。","通过这次活动，大家认识了很多新朋友。","大家通过了认识很多新朋友这次活动。","通过大家这次活动，认识了很多新朋友了。"],"answer":1,"explain":{"vi":"通过 + phương tiện đứng đầu câu, sau đó mới là chủ ngữ và kết quả.","en":"通过 + means opens the sentence, then come the subject and the result."}}]},
  {"id":"g36","title":{"zh":"由","vi":"Giới từ 由 (do… đảm nhận)","en":"由 (done by, up to)"},"pattern":"(O) + 由 + agent + V (负责 / 决定 / 安排 / 解决) | 由 + parts + 组成","explain":{"vi":"由 giới thiệu người chịu trách nhiệm làm việc gì (\"do… phụ trách, do… quyết định\"), không mang sắc thái bị động tiêu cực như 被. Lỗi hay gặp: dùng 被 khi chỉ phân công công việc (会议被经理负责 là sai).","en":"由 introduces whoever is responsible for doing something (\"handled by, decided by\") and has none of the adverse passive feel of 被. Common mistake: using 被 when simply assigning duties."},"examples":[{"zh":"这次活动由人事部负责安排。","py":"Zhè cì huódòng yóu rénshìbù fùzé ānpái.","vi":"Hoạt động lần này do phòng nhân sự phụ trách sắp xếp.","en":"This event is arranged by the HR department."},{"zh":"去还是不去，由你自己决定。","py":"Qù háishi bú qù, yóu nǐ zìjǐ juédìng.","vi":"Đi hay không đi là do chính bạn quyết định.","en":"Whether to go or not is up to you."}],"quiz":[{"q":"明天的会议____王经理负责。","options":["被","由","把","对"],"answer":1,"explain":{"vi":"Chỉ người phụ trách công việc dùng 由, không dùng 被.","en":"Use 由, not 被, for the person in charge of a task."}},{"q":"这件事应该由____来决定？","options":["什么","怎么","哪儿","谁"],"answer":3,"explain":{"vi":"Sau 由 là người thực hiện, nên hỏi bằng 谁.","en":"由 is followed by the doer, so the question word is 谁."}},{"q":"我们的小组由五个人____。","options":["组成","完成","变成","成为"],"answer":0,"explain":{"vi":"由…组成: do… tạo thành.","en":"由…组成 means \"is made up of\"."}},{"q":"我的自行车____弟弟骑坏了。","options":["由","对","被","向"],"answer":2,"explain":{"vi":"Việc không mong muốn xảy ra với chủ ngữ dùng 被, không dùng 由.","en":"Something unwanted happening to the subject takes 被, not 由."}},{"q":"下面哪个句子是正确的？","options":["新员工的材料小李由整理。","由新员工的材料小李整理。","新员工的材料由小李整理。","新员工的材料整理由小李了。"],"answer":2,"explain":{"vi":"Trật tự: đối tượng + 由 + người làm + động từ.","en":"Order: object + 由 + doer + verb."}}]},
  {"id":"g37","title":{"zh":"向 / 往 / 朝","vi":"Giới từ chỉ hướng 向 / 往 / 朝","en":"向 / 往 / 朝 (towards)"},"pattern":"向 / 往 / 朝 + direction + V | 向 + person + V (学习 / 道歉 / 介绍 / 表示) | V (开 / 飞 / 寄 / 送) + 往 + place","explain":{"vi":"Cả ba đều chỉ hướng của hành động. 往 chỉ đi với nơi chốn, phương hướng, không đi với người. 向 và 朝 đi được với người, nhưng với động từ trừu tượng (学习, 道歉, 介绍) chỉ dùng 向. Lỗi hay gặp: nói 往他道歉.","en":"All three mark the direction of an action. 往 takes only places or directions, never a person. 向 and 朝 can take a person, but abstract verbs (学习, 道歉, 介绍) take only 向. Common mistake: 往他道歉."},"examples":[{"zh":"一直往前走，到路口向右转。","py":"Yìzhí wǎng qián zǒu, dào lùkǒu xiàng yòu zhuǎn.","vi":"Cứ đi thẳng về phía trước, đến ngã tư thì rẽ phải.","en":"Go straight ahead and turn right at the crossing."},{"zh":"我们应该向有经验的同事学习。","py":"Wǒmen yīnggāi xiàng yǒu jīngyàn de tóngshì xuéxí.","vi":"Chúng ta nên học hỏi những đồng nghiệp có kinh nghiệm.","en":"We should learn from experienced colleagues."}],"quiz":[{"q":"这件事是我错了，我____你道歉。","options":["往","向","朝","从"],"answer":1,"explain":{"vi":"Với động từ trừu tượng như 道歉 và đối tượng là người, chỉ dùng 向.","en":"With an abstract verb like 道歉 and a person, only 向 works."}},{"q":"这趟火车是开____上海的。","options":["朝","对","给","往"],"answer":3,"explain":{"vi":"Động từ + 往 + nơi đến: 开往上海.","en":"Verb + 往 + destination: 开往上海."}},{"q":"他____我笑了笑，没有说话。","options":["往","从","朝","由"],"answer":2,"explain":{"vi":"Hướng mặt về phía một người dùng 朝 (hoặc 向); 往 không đi với người.","en":"Facing a person takes 朝 (or 向); 往 cannot take a person."}},{"q":"请大家____老师介绍一下自己。","options":["向","往","朝","在"],"answer":0,"explain":{"vi":"向 + người + 介绍: giới thiệu với ai.","en":"向 + person + 介绍 means \"introduce to someone\"."}},{"q":"下面哪个句子是正确的？","options":["你左边往看，那就是我们公司。","你往左边看，那就是我们公司。","往你左边看那，就是我们公司。","你看左边往，那就是我们公司。"],"answer":1,"explain":{"vi":"往 + phương hướng đứng trước động từ.","en":"往 + direction goes before the verb."}}]},
  {"id":"g38","title":{"zh":"为了 / 为","vi":"Giới từ 为了 / 为","en":"为了 / 为 (in order to / for)"},"pattern":"为了 + purpose，S + V | S + 为 + person / thing + V | 为 + N + 高兴 / 担心 / 着急","explain":{"vi":"为了 nêu mục đích, thường đứng đầu câu. 为 chỉ đối tượng được phục vụ hoặc nguyên nhân của cảm xúc. Lỗi hay gặp: dùng 为了 để nêu nguyên nhân thay cho 因为 (为了下雨，我没去 là sai).","en":"为了 gives a purpose and usually opens the sentence. 为 marks who benefits, or the cause of a feeling. Common mistake: using 为了 for a cause instead of 因为 (为了下雨，我没去 is wrong)."},"examples":[{"zh":"为了提高汉语水平，她每天看中文新闻。","py":"Wèile tígāo Hànyǔ shuǐpíng, tā měi tiān kàn Zhōngwén xīnwén.","vi":"Để nâng cao trình độ tiếng Trung, ngày nào cô ấy cũng xem tin tức tiếng Trung.","en":"To improve her Chinese, she reads Chinese news every day."},{"zh":"公司为新员工准备了很多材料。","py":"Gōngsī wèi xīn yuángōng zhǔnbèi le hěn duō cáiliào.","vi":"Công ty đã chuẩn bị rất nhiều tài liệu cho nhân viên mới.","en":"The company has prepared a lot of material for new staff."}],"quiz":[{"q":"____不迟到，他每天六点就起床。","options":["因为","由于","关于","为了"],"answer":3,"explain":{"vi":"Nêu mục đích (để không đến muộn) dùng 为了.","en":"A purpose (so as not to be late) takes 为了."}},{"q":"____路上堵车，我今天迟到了。","options":["因为","为了","为","按照"],"answer":0,"explain":{"vi":"Nêu nguyên nhân dùng 因为, không dùng 为了.","en":"A cause takes 因为, not 为了."}},{"q":"听说你通过了考试，我真____你高兴。","options":["为了","为","对","向"],"answer":1,"explain":{"vi":"为 + người + 高兴: mừng cho ai.","en":"为 + person + 高兴 means \"happy for someone\"."}},{"q":"我们都愿意____顾客提供更好的服务。","options":["为了","对于","为","被"],"answer":2,"explain":{"vi":"为 + đối tượng được phục vụ + 提供服务.","en":"为 + beneficiary + 提供服务."}},{"q":"下面哪个句子是正确的？","options":["保护环境为了，我们应该少用塑料袋。","我们为了应该保护环境少用塑料袋。","为保护了环境，我们应该少用塑料袋。","为了保护环境，我们应该少用塑料袋。"],"answer":3,"explain":{"vi":"为了 + mục đích đứng đầu câu, sau đó là hành động.","en":"为了 + purpose opens the sentence, followed by the action."}}]},
  {"id":"g39","title":{"zh":"到底 / 究竟","vi":"Phó từ truy hỏi 到底 / 究竟","en":"到底 / 究竟 (on earth, after all)"},"pattern":"S + 到底 / 究竟 + question word / A还是B / V不V ？ | 到底 / 究竟 + 谁 / 什么 (as subject) + V ？","explain":{"vi":"Dùng trong câu hỏi để truy hỏi \"rốt cuộc\"; 究竟 trang trọng hơn. Lỗi hay gặp: dùng trong câu hỏi có 吗 (你到底去吗？ là sai, phải nói 你到底去不去？). Nếu chủ ngữ là từ để hỏi thì 到底 đứng trước nó (到底谁去？).","en":"Used in questions to press for a real answer; 究竟 is more formal. Common mistake: using it in a 吗 question (你到底去吗？ is wrong; say 你到底去不去？). If the subject is the question word, 到底 goes before it (到底谁去？)."},"examples":[{"zh":"你到底同意不同意这个计划？","py":"Nǐ dàodǐ tóngyì bu tóngyì zhège jìhuà?","vi":"Rốt cuộc bạn có đồng ý với kế hoạch này không?","en":"Do you agree with this plan or not?"},{"zh":"这究竟是怎么回事，谁能告诉我？","py":"Zhè jiūjìng shì zěnme huí shì, shéi néng gàosu wǒ?","vi":"Rốt cuộc chuyện này là thế nào, ai có thể nói cho tôi biết?","en":"What on earth is going on? Can anyone tell me?"}],"quiz":[{"q":"下面哪个句子是正确的？","options":["你到底去吗？","你到底去不去？","你去不去到底？","到底你去吗？"],"answer":1,"explain":{"vi":"到底 không dùng trong câu hỏi 吗; nó đứng trước phần nghi vấn.","en":"到底 is not used in 吗 questions and goes before the question part."}},{"q":"____谁拿走了我的词典？","options":["难道","恐怕","千万","到底"],"answer":3,"explain":{"vi":"Chủ ngữ là từ để hỏi 谁, nên 到底 đứng trước nó để truy hỏi.","en":"The subject is the question word 谁, so 到底 goes before it."}},{"q":"他究竟____才来？","options":["明天","什么时候","已经","马上"],"answer":1,"explain":{"vi":"Sau 究竟 phải có hình thức nghi vấn (什么时候).","en":"究竟 needs a question form after it (什么时候)."}},{"q":"你们到底想坐火车____坐飞机？","options":["还是","或者","而且","而是"],"answer":0,"explain":{"vi":"Câu hỏi lựa chọn dùng 还是.","en":"A choice question uses 还是."}},{"q":"你____知道不知道这件事？","options":["难道","也许","究竟","大概"],"answer":2,"explain":{"vi":"Câu hỏi chính phản (知道不知道) đi với 究竟/到底; 难道 đi với câu hỏi 吗.","en":"A V不V question takes 究竟/到底; 难道 goes with 吗 questions."}}]},
  {"id":"g40","title":{"zh":"千万","vi":"Phó từ 千万 (nhất thiết, tuyệt đối)","en":"千万 (be sure to, never)"},"pattern":"(你) + 千万 + 要 / 别 / 不要 / 不能 + V","explain":{"vi":"Dùng khi dặn dò, nhắc nhở tha thiết: \"nhất định phải…, tuyệt đối đừng…\". Chỉ dùng trong câu cầu khiến với người nghe. Lỗi hay gặp: dùng 千万 nói về quyết tâm của chính mình (我千万要去 là sai, phải nói 我一定要去).","en":"Used for earnest reminders: \"be sure to…, whatever you do, don't…\". It only appears in requests to the listener. Common mistake: using it for one's own determination (我千万要去 is wrong; say 我一定要去)."},"examples":[{"zh":"明天的会议很重要，你千万别迟到。","py":"Míngtiān de huìyì hěn zhòngyào, nǐ qiānwàn bié chídào.","vi":"Cuộc họp ngày mai rất quan trọng, bạn tuyệt đối đừng đến muộn.","en":"Tomorrow's meeting is important; whatever you do, don't be late."},{"zh":"这个密码千万要记住，不能告诉别人。","py":"Zhège mìmǎ qiānwàn yào jìzhù, bù néng gàosu biérén.","vi":"Mật khẩu này nhất định phải nhớ, không được nói cho người khác.","en":"Be sure to remember this password and never tell anyone."}],"quiz":[{"q":"开车的时候____不要看手机。","options":["到底","难道","千万","恐怕"],"answer":2,"explain":{"vi":"Lời nhắc nhở \"tuyệt đối đừng\" dùng 千万不要.","en":"An earnest warning takes 千万不要."}},{"q":"我____要通过这次考试。","options":["千万","难道","究竟","一定"],"answer":3,"explain":{"vi":"Nói về quyết tâm của bản thân dùng 一定, không dùng 千万.","en":"One's own determination takes 一定, not 千万."}},{"q":"下面哪个句子是正确的？","options":["你别千万忘了带护照。","你千万别忘了带护照。","千万你忘了别带护照。","你千万忘了带护照。"],"answer":1,"explain":{"vi":"千万 đứng trước 别/不要.","en":"千万 goes before 别/不要."}},{"q":"这些材料很重要，千万____弄丢了。","options":["别","没","不","很"],"answer":0,"explain":{"vi":"千万 + 别 + động từ: tuyệt đối đừng….","en":"千万 + 别 + verb: \"never…\"."}},{"q":"“千万”常常用在什么样的句子里？","options":["问问题的句子","说自己打算的句子","提醒别人的句子","比较两个东西的句子"],"answer":2,"explain":{"vi":"千万 dùng trong câu dặn dò, nhắc nhở người khác.","en":"千万 is used when reminding or warning someone."}}]},
  {"id":"g41","title":{"zh":"恐怕","vi":"Phó từ 恐怕 (e rằng)","en":"恐怕 (I'm afraid, probably)"},"pattern":"恐怕 + (S) + 会 / 要 / 不能 / V不… (a worried guess)","explain":{"vi":"Nêu một phán đoán kèm lo lắng: \"e rằng, có lẽ\". 恐怕 là phó từ, đứng trước hoặc sau chủ ngữ. Lỗi hay gặp: dùng 恐怕 như động từ \"sợ\" (我恐怕狗 là sai, phải nói 我怕狗).","en":"Gives a guess coloured by worry: \"I'm afraid, probably\". 恐怕 is an adverb and goes before or after the subject. Common mistake: using it as the verb \"to fear\" (我恐怕狗 is wrong; say 我怕狗)."},"examples":[{"zh":"已经八点了，我们恐怕要迟到了。","py":"Yǐjīng bā diǎn le, wǒmen kǒngpà yào chídào le.","vi":"Đã tám giờ rồi, e rằng chúng ta sắp muộn mất.","en":"It's already eight; I'm afraid we are going to be late."},{"zh":"这么多材料，今天恐怕整理不完。","py":"Zhème duō cáiliào, jīntiān kǒngpà zhěnglǐ bu wán.","vi":"Nhiều tài liệu thế này, hôm nay e là sắp xếp không xong.","en":"With so many documents, I'm afraid we can't finish sorting them today."}],"quiz":[{"q":"天这么阴，____要下雨了。","options":["千万","到底","恐怕","难道"],"answer":2,"explain":{"vi":"Phán đoán kèm lo lắng dùng 恐怕.","en":"A worried guess takes 恐怕."}},{"q":"我从小就____狗。","options":["恐怕","怕","可怕","害羞"],"answer":1,"explain":{"vi":"\"Sợ\" cái gì là động từ 怕; 恐怕 là phó từ nên không mang tân ngữ.","en":"\"To fear something\" is the verb 怕; 恐怕 is an adverb and takes no object."}},{"q":"下面哪个句子是正确的？","options":["他恐怕不会同意。","他不会恐怕同意。","恐怕他同意不会。","他恐怕老虎。"],"answer":0,"explain":{"vi":"恐怕 đứng trước cả cụm vị ngữ (不会同意).","en":"恐怕 goes before the whole predicate (不会同意)."}},{"q":"这个周末我有事，恐怕____。","options":["一定要参加聚会","参加过聚会","千万别参加聚会","不能参加聚会了"],"answer":3,"explain":{"vi":"Sau 恐怕 là điều không mong muốn mà người nói dự đoán.","en":"恐怕 is followed by the unwelcome thing the speaker expects."}},{"q":"“恐怕”表示说话人：","options":["非常肯定","担心地估计","提醒别人","觉得奇怪"],"answer":1,"explain":{"vi":"恐怕 = phỏng đoán có kèm lo lắng.","en":"恐怕 expresses a guess with some worry."}}]},
  {"id":"g42","title":{"zh":"竟然","vi":"Phó từ 竟然 (không ngờ lại)","en":"竟然 (unexpectedly)"},"pattern":"S + 竟然 + V / Adj","explain":{"vi":"Diễn tả việc xảy ra ngoài dự đoán, người nói thấy bất ngờ. 竟然 là phó từ, đứng sau chủ ngữ và trước vị ngữ. Lỗi hay gặp: nhầm với 果然 (đúng như dự đoán).","en":"Says that something happened against expectation and surprised the speaker. 竟然 is an adverb placed after the subject, before the predicate. Common mistake: confusing it with 果然 (just as expected)."},"examples":[{"zh":"这么重要的会议，他竟然忘了参加。","py":"Zhème zhòngyào de huìyì, tā jìngrán wàng le cānjiā.","vi":"Cuộc họp quan trọng thế này mà anh ấy lại quên tham dự.","en":"Such an important meeting, and he actually forgot to attend."},{"zh":"才学了半年，她的汉语竟然这么流利。","py":"Cái xué le bàn nián, tā de Hànyǔ jìngrán zhème liúlì.","vi":"Mới học nửa năm mà tiếng Trung của cô ấy lại lưu loát thế này.","en":"After only half a year of study, her Chinese is surprisingly fluent."}],"quiz":[{"q":"我们是邻居，他____不知道我姓什么。","options":["果然","千万","尤其","竟然"],"answer":3,"explain":{"vi":"Là hàng xóm mà không biết họ là điều bất ngờ, dùng 竟然.","en":"Not knowing a neighbour's surname is unexpected, so 竟然."}},{"q":"天气预报说今天有雨，下午____下雨了。","options":["竟然","果然","千万","究竟"],"answer":1,"explain":{"vi":"Việc xảy ra đúng như dự báo dùng 果然, không dùng 竟然.","en":"What happens as forecast takes 果然, not 竟然."}},{"q":"下面哪个句子是正确的？","options":["他一个人竟然了完成任务。","他一个人完成了竟然任务。","他竟然一个人完成了任务。","他完成了任务竟然一个人。"],"answer":2,"explain":{"vi":"竟然 đứng sau chủ ngữ, trước phần vị ngữ.","en":"竟然 follows the subject and precedes the predicate."}},{"q":"“他竟然没迟到”说明说话人：","options":["没想到他没迟到","早就知道他不会迟到","希望他迟到","不知道他迟到没有"],"answer":0,"explain":{"vi":"竟然 cho thấy người nói không ngờ tới.","en":"竟然 shows the speaker did not expect it."}},{"q":"这道题很简单，他____做错了。","options":["果然","竟然","顺便","稍微"],"answer":1,"explain":{"vi":"Bài dễ mà làm sai là ngoài dự đoán.","en":"Getting an easy question wrong is unexpected."}}]},
  {"id":"g43","title":{"zh":"果然","vi":"Phó từ 果然 (quả nhiên)","en":"果然 (sure enough)"},"pattern":"(S) + 果然 + V / Adj | …，果然，+ clause","explain":{"vi":"Diễn tả sự việc xảy ra đúng như đã nói hoặc đã đoán trước đó. Phía trước thường có lời dự đoán, lời đồn hay dự báo. Lỗi hay gặp: nhầm với 竟然 (trái dự đoán) hoặc 当然 (đương nhiên).","en":"Says that things turned out exactly as said or guessed earlier. A prediction, rumour or forecast usually comes first. Common mistake: confusing it with 竟然 (against expectation) or 当然 (of course)."},"examples":[{"zh":"听说那家饭馆不错，去了以后果然很好吃。","py":"Tīngshuō nà jiā fànguǎn búcuò, qù le yǐhòu guǒrán hěn hǎochī.","vi":"Nghe nói quán đó khá ngon, đến rồi thấy quả nhiên rất ngon.","en":"I heard that restaurant was good, and sure enough the food was delicious."},{"zh":"大家都说他会成功，他果然成功了。","py":"Dàjiā dōu shuō tā huì chénggōng, tā guǒrán chénggōng le.","vi":"Mọi người đều nói anh ấy sẽ thành công, quả nhiên anh ấy đã thành công.","en":"Everyone said he would succeed, and sure enough he did."}],"quiz":[{"q":"我猜他今天会迟到，他____迟到了。","options":["果然","竟然","千万","难道"],"answer":0,"explain":{"vi":"Sự việc đúng như đã đoán dùng 果然.","en":"What happens as guessed takes 果然."}},{"q":"他平时成绩很差，这次____考了第一名。","options":["果然","顺便","竟然","按时"],"answer":2,"explain":{"vi":"Kết quả trái với dự đoán dùng 竟然, không dùng 果然.","en":"A result against expectation takes 竟然, not 果然."}},{"q":"“果然”表示：","options":["事情和想的不一样","事情还没发生","事情很重要","事情和想的一样"],"answer":3,"explain":{"vi":"果然 = đúng như đã nghĩ, đã nói.","en":"果然 means \"just as thought or said\"."}},{"q":"朋友说这个电影很让人感动，我看了以后，____哭了。","options":["曾经","果然","千万","稍微"],"answer":1,"explain":{"vi":"Đúng như lời bạn nói nên dùng 果然.","en":"It turned out as the friend said, so 果然."}},{"q":"医生说休息几天就好了，____，三天以后他就不发烧了。","options":["然而","否则","果然","竟然"],"answer":2,"explain":{"vi":"Kết quả đúng như bác sĩ nói.","en":"The result matched what the doctor said."}}]},
  {"id":"g44","title":{"zh":"几乎 / 差点儿","vi":"几乎 (gần như) / 差点儿 (suýt nữa)","en":"几乎 / 差点儿 (almost / nearly)"},"pattern":"几乎 + 都 / 全 / 每 / 所有 / 没有… | 差点儿 + V (did not happen) | 差点儿 + 没 + V","explain":{"vi":"几乎: gần như toàn bộ, nói về số lượng, phạm vi. 差点儿: suýt nữa thì xảy ra. Với việc không mong muốn, 差点儿迟到 và 差点儿没迟到 đều nghĩa là \"không muộn\". Với việc mong muốn, 差点儿赶上 = không kịp, còn 差点儿没赶上 = may mà kịp. Lỗi hay gặp: hiểu 差点儿迟到 là \"đã muộn\".","en":"几乎: nearly all, about quantity or range. 差点儿: something nearly happened. For unwanted events, 差点儿迟到 and 差点儿没迟到 both mean \"was not late\". For wanted events, 差点儿赶上 = missed it, while 差点儿没赶上 = only just made it. Common mistake: reading 差点儿迟到 as \"was late\"."},"examples":[{"zh":"办公室里几乎所有人都认识他。","py":"Bàngōngshì lǐ jīhū suǒyǒu rén dōu rènshi tā.","vi":"Trong văn phòng gần như ai cũng biết anh ấy.","en":"Almost everyone in the office knows him."},{"zh":"今天路上堵车，我差点儿迟到。","py":"Jīntiān lùshang dǔchē, wǒ chàdiǎnr chídào.","vi":"Hôm nay đường tắc, tôi suýt nữa thì đến muộn.","en":"There was a traffic jam today and I was nearly late."}],"quiz":[{"q":"“我差点儿迟到”的意思是：","options":["我迟到了","我没迟到","我经常迟到","我不会迟到"],"answer":1,"explain":{"vi":"差点儿 + việc không mong muốn = việc đó chưa xảy ra.","en":"差点儿 + an unwanted event means it did not happen."}},{"q":"“他差点儿就考上了”的意思是：","options":["他考上了","他不想考","他还没考","他没考上"],"answer":3,"explain":{"vi":"差点儿 + việc mong muốn = tiếc là không đạt được.","en":"差点儿 + a wanted event means it sadly did not happen."}},{"q":"这里的人我____都不认识。","options":["几乎","差点儿","稍微","千万"],"answer":0,"explain":{"vi":"Nói về phạm vi \"gần như tất cả\" dùng 几乎.","en":"\"Nearly all\" in range takes 几乎."}},{"q":"我今天起晚了，____没赶上公共汽车。","options":["稍微","尤其","差点儿","到底"],"answer":2,"explain":{"vi":"差点儿没赶上 = suýt nữa thì lỡ, nhưng cuối cùng vẫn kịp.","en":"差点儿没赶上 = nearly missed it, but caught it in the end."}},{"q":"他忙得____没有时间吃饭。","options":["尤其","几乎","果然","顺便"],"answer":1,"explain":{"vi":"几乎没有: gần như không có.","en":"几乎没有 means \"have almost no\"."}}]},
  {"id":"g45","title":{"zh":"稍微","vi":"Phó từ 稍微 (hơi, một chút)","en":"稍微 (slightly, a little)"},"pattern":"稍微 + V + 一下 / 一会儿 / 一点儿 | 稍微 + Adj + 一点儿 | 稍微 + 有点儿 + Adj","explain":{"vi":"Chỉ mức độ nhẹ hoặc thời gian ngắn. Sau 稍微 luôn phải có từ chỉ lượng ít: 一下, 一会儿, 一点儿, 有点儿. Lỗi hay gặp: dùng 稍微 một mình (请稍微等 là sai, phải nói 请稍微等一下).","en":"Marks a slight degree or a short time. 稍微 must be backed up by a small-quantity word: 一下, 一会儿, 一点儿, 有点儿. Common mistake: using 稍微 alone (请稍微等 is wrong; say 请稍微等一下)."},"examples":[{"zh":"请您稍微等一下，经理马上就来。","py":"Qǐng nín shāowēi děng yíxià, jīnglǐ mǎshàng jiù lái.","vi":"Xin ông đợi một chút, giám đốc sẽ đến ngay.","en":"Please wait a moment; the manager will be right here."},{"zh":"这条裤子稍微长了一点儿。","py":"Zhè tiáo kùzi shāowēi cháng le yìdiǎnr.","vi":"Cái quần này hơi dài một chút.","en":"These trousers are a little too long."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["你稍微休息吧。","你休息稍微一会儿吧。","你稍微休息一会儿吧。","你一会儿稍微休息吧。"],"answer":2,"explain":{"vi":"稍微 đứng trước động từ, sau động từ phải có từ chỉ lượng ít (一会儿).","en":"稍微 goes before the verb, and a small-quantity word (一会儿) must follow the verb."}},{"q":"今天比昨天____冷一点儿。","options":["非常","十分","太","稍微"],"answer":3,"explain":{"vi":"Trong câu 比 có 一点儿, chỉ dùng được 稍微; 非常/十分/太 không dùng trong câu 比.","en":"In a 比 sentence with 一点儿 only 稍微 fits; 非常/十分/太 cannot be used with 比."}},{"q":"这个菜稍微____咸。","options":["有点儿","很","非常","太"],"answer":0,"explain":{"vi":"稍微 + 有点儿 + tính từ.","en":"稍微 + 有点儿 + adjective."}},{"q":"请把声音开得稍微大____。","options":["极了","一点儿","得很","多了"],"answer":1,"explain":{"vi":"稍微 + tính từ + 一点儿.","en":"稍微 + adjective + 一点儿."}},{"q":"“稍微”后面常常要有：","options":["表示否定的词","表示时间长的词","表示数量少的词","表示程度高的词"],"answer":2,"explain":{"vi":"稍微 cần đi với 一点儿, 一下, 一会儿….","en":"稍微 needs words like 一点儿, 一下, 一会儿."}}]},
  {"id":"g46","title":{"zh":"尤其","vi":"Phó từ 尤其 (nhất là)","en":"尤其 (especially)"},"pattern":"general statement，尤其 (是) + N | S + 尤其 + V / Adj","explain":{"vi":"Nêu một phần nổi bật hơn hẳn trong một nhóm đã nói ở trước: \"nhất là, đặc biệt là\". Phía trước phải có phạm vi chung. Lỗi hay gặp: dùng 尤其 làm tính từ \"đặc biệt\" (这件衣服很尤其 là sai, phải dùng 特别).","en":"Singles out one member of a group already mentioned: \"especially\". A general statement must come first. Common mistake: using 尤其 as the adjective \"special\" (这件衣服很尤其 is wrong; use 特别)."},"examples":[{"zh":"我喜欢吃水果，尤其是西瓜。","py":"Wǒ xǐhuan chī shuǐguǒ, yóuqí shì xīguā.","vi":"Tôi thích ăn hoa quả, nhất là dưa hấu.","en":"I like fruit, especially watermelon."},{"zh":"这几个月大家都很忙，尤其是星期一。","py":"Zhè jǐ ge yuè dàjiā dōu hěn máng, yóuqí shì xīngqīyī.","vi":"Mấy tháng nay mọi người đều rất bận, nhất là thứ Hai.","en":"Everyone has been busy these months, especially on Mondays."}],"quiz":[{"q":"办公室的同事都很热情，____是小张。","options":["几乎","尤其","稍微","千万"],"answer":1,"explain":{"vi":"Nêu một người nổi bật trong nhóm dùng 尤其是.","en":"Singling out one person in the group takes 尤其是."}},{"q":"这件衣服的样子很____。","options":["尤其","尤其是","几乎","特别"],"answer":3,"explain":{"vi":"Làm tính từ \"đặc biệt\" phải dùng 特别; 尤其 chỉ là phó từ.","en":"As the adjective \"special\" you need 特别; 尤其 is only an adverb."}},{"q":"北方的冬天很冷，____是一月。","options":["尤其","于是","可是","要是"],"answer":0,"explain":{"vi":"Trong mùa đông, tháng Một là nổi bật nhất.","en":"Within winter, January stands out most."}},{"q":"下面哪个句子是正确的？","options":["他尤其是数学，各门课都很好。","尤其他各门课都很好是数学。","他各门课都很好，尤其是数学。","他各门课尤其都很好，是数学。"],"answer":2,"explain":{"vi":"Nêu phạm vi chung trước, sau đó mới dùng 尤其是.","en":"State the general range first, then 尤其是."}},{"q":"我对中国文化很感兴趣，尤其____。","options":["很感兴趣","是京剧","不喜欢","是因为"],"answer":1,"explain":{"vi":"Sau 尤其是 là một phần cụ thể của 中国文化.","en":"尤其是 is followed by one specific part of 中国文化."}}]},
  {"id":"g47","title":{"zh":"顺便","vi":"Phó từ 顺便 (tiện thể)","en":"顺便 (while you're at it)"},"pattern":"S + V1 (main action)，顺便 + V2 (extra action)","explain":{"vi":"Nhân lúc làm việc chính thì tiện làm thêm một việc khác. Việc chính nói trước, 顺便 đứng trước việc làm thêm. Lỗi hay gặp: nhầm với 随便 (tùy ý, tùy tiện).","en":"While doing the main thing, you take the chance to do something extra. The main action comes first and 顺便 goes before the extra one. Common mistake: confusing it with 随便 (as one pleases, casual)."},"examples":[{"zh":"你去银行的时候，顺便帮我取点儿钱。","py":"Nǐ qù yínháng de shíhou, shùnbiàn bāng wǒ qǔ diǎnr qián.","vi":"Lúc bạn đi ngân hàng, tiện thể rút giúp tôi ít tiền.","en":"When you go to the bank, please withdraw some money for me while you're there."},{"zh":"我下班回家，顺便去超市买了点儿菜。","py":"Wǒ xiàbān huí jiā, shùnbiàn qù chāoshì mǎi le diǎnr cài.","vi":"Tôi tan làm về nhà, tiện đường ghé siêu thị mua ít rau.","en":"On my way home from work I stopped by the supermarket to buy some vegetables."}],"quiz":[{"q":"你出去的时候，____把门关上。","options":["随便","方便","尤其","顺便"],"answer":3,"explain":{"vi":"Nhân lúc đi ra ngoài thì làm thêm một việc dùng 顺便.","en":"Doing something extra on the way out takes 顺便."}},{"q":"这些水果你____吃，别客气。","options":["随便","顺便","稍微","果然"],"answer":0,"explain":{"vi":"\"Cứ tự nhiên, tùy ý\" là 随便.","en":"\"As you please\" is 随便."}},{"q":"我去北京出差，____看了看老同学。","options":["究竟","恐怕","顺便","千万"],"answer":2,"explain":{"vi":"Việc chính là đi công tác, thăm bạn là việc tiện thể.","en":"The business trip is the main thing; visiting a classmate is the extra."}},{"q":"“我去邮局寄信，顺便买了几张邮票”，他去邮局主要是为了：","options":["买邮票","寄信","见朋友","散步"],"answer":1,"explain":{"vi":"Việc chính đứng trước 顺便.","en":"The main purpose is stated before 顺便."}},{"q":"我去打印合同，____帮你打印一份吧。","options":["否则","曾经","到底","顺便"],"answer":3,"explain":{"vi":"Nhân tiện đi in thì in giúp luôn.","en":"Since I'm printing anyway, I'll print yours too."}}]},
  {"id":"g48","title":{"zh":"仍然","vi":"Phó từ 仍然 (vẫn)","en":"仍然 (still)"},"pattern":"S + 仍然 + V / Adj | 虽然 / 尽管…，S + 仍然… | 仍然 + 不 / 没","explain":{"vi":"Tình hình vẫn như cũ, không thay đổi; trang trọng hơn 还是. 仍然 đứng sau chủ ngữ, và đứng trước 不/没. Lỗi hay gặp: đặt 仍然 sau từ phủ định (没有仍然解决 là sai).","en":"The situation continues unchanged; more formal than 还是. 仍然 follows the subject and comes before 不/没. Common mistake: placing it after the negative (没有仍然解决 is wrong)."},"examples":[{"zh":"已经十二点了，他仍然在办公室工作。","py":"Yǐjīng shí'èr diǎn le, tā réngrán zài bàngōngshì gōngzuò.","vi":"Đã mười hai giờ rồi mà anh ấy vẫn làm việc ở văn phòng.","en":"It's already twelve and he is still working in the office."},{"zh":"虽然失败了很多次，她仍然没有放弃。","py":"Suīrán shībài le hěn duō cì, tā réngrán méiyǒu fàngqì.","vi":"Tuy thất bại nhiều lần, cô ấy vẫn không bỏ cuộc.","en":"Although she failed many times, she still has not given up."}],"quiz":[{"q":"十年过去了，他____住在那个小城市。","options":["曾经","顺便","仍然","刚才"],"answer":2,"explain":{"vi":"Tình hình không thay đổi sau mười năm dùng 仍然.","en":"An unchanged situation after ten years takes 仍然."}},{"q":"下面哪个句子是正确的？","options":["问题没有仍然解决。","问题仍然没有解决。","仍然问题没有解决。","问题没有解决仍然。"],"answer":1,"explain":{"vi":"仍然 đứng sau chủ ngữ và trước 没有.","en":"仍然 follows the subject and precedes 没有."}},{"q":"尽管大家都反对，他____坚持自己的看法。","options":["于是","因此","否则","仍然"],"answer":3,"explain":{"vi":"尽管…仍然…: dù… vẫn….","en":"尽管…仍然… means \"although… still…\"."}},{"q":"“仍然”的意思和下面哪个词差不多？","options":["还是","已经","马上","刚才"],"answer":0,"explain":{"vi":"仍然 gần nghĩa với 还是 (vẫn).","en":"仍然 is close in meaning to 还是 (still)."}},{"q":"雨从早上下到晚上，现在____。","options":["仍然停了","仍然在下","曾经下过","从来不下"],"answer":1,"explain":{"vi":"仍然 chỉ trạng thái tiếp tục, nên là \"vẫn đang mưa\".","en":"仍然 marks continuation, so \"it is still raining\"."}}]},
  {"id":"g49","title":{"zh":"一直 / 从来","vi":"一直 (luôn, suốt) / 从来 (từ trước đến nay)","en":"一直 / 从来 (all along / never)"},"pattern":"S + 一直 + V / Adj | 一直 + 往 / 向 + direction + V | S + 从来 + 不 / 没 + V (+ 过)","explain":{"vi":"一直: hành động, trạng thái kéo dài không ngừng, hoặc đi thẳng một hướng. 从来: từ trước đến giờ, hầu như chỉ dùng với phủ định (从来不, 从来没…过). Lỗi hay gặp: dùng 从来 trong câu khẳng định (我从来喝茶 là sai).","en":"一直: an action or state continues without a break, or movement goes straight on. 从来: at any time up to now, almost always with a negative (从来不, 从来没…过). Common mistake: using 从来 in an affirmative sentence (我从来喝茶 is wrong)."},"examples":[{"zh":"她从来不迟到，也从来没请过假。","py":"Tā cónglái bù chídào, yě cónglái méi qǐng guo jià.","vi":"Cô ấy không bao giờ đến muộn, cũng chưa từng xin nghỉ.","en":"She is never late and has never taken leave."},{"zh":"我一直在等人事部的通知。","py":"Wǒ yìzhí zài děng rénshìbù de tōngzhī.","vi":"Tôi vẫn luôn chờ thông báo của phòng nhân sự.","en":"I have been waiting for the notice from HR all along."}],"quiz":[{"q":"这么奇怪的事，我____没听说过。","options":["曾经","刚才","稍微","从来"],"answer":3,"explain":{"vi":"从来没…过: từ trước đến nay chưa từng.","en":"从来没…过 means \"have never\"."}},{"q":"雨____下了三天，到现在还没停。","options":["从来","一直","曾经","刚才"],"answer":1,"explain":{"vi":"Hành động kéo dài không ngừng dùng 一直.","en":"An action that goes on without stopping takes 一直."}},{"q":"下面哪个句子是正确的？","options":["他从来喝酒。","他不从来喝酒。","他从来不喝酒。","从来他喝不酒。"],"answer":2,"explain":{"vi":"从来 đứng trước 不, và dùng trong câu phủ định.","en":"从来 goes before 不 and is used in negative sentences."}},{"q":"从这儿____往前走，就能看到地铁站。","options":["一直","从来","曾经","已经"],"answer":0,"explain":{"vi":"一直往前走: đi thẳng về phía trước.","en":"一直往前走 means \"go straight ahead\"."}},{"q":"我从来没____这么好吃的饺子。","options":["吃了","吃过","吃着","在吃"],"answer":1,"explain":{"vi":"从来没 + động từ + 过.","en":"从来没 + verb + 过."}}]},
  {"id":"g50","title":{"zh":"曾经 / 已经","vi":"曾经 (đã từng) / 已经 (đã… rồi)","en":"曾经 / 已经 (once / already)"},"pattern":"S + 曾经 + V + 过 (in the past, no longer true) | S + 已经 + V / Adj + 了 (done, still relevant) | negative: 没 (有) + V + 过","explain":{"vi":"曾经: việc từng xảy ra trong quá khứ và nay đã hết, thường đi với 过. 已经: việc đã hoàn thành hoặc đã đạt mức nào đó, còn liên quan đến hiện tại, thường đi với 了. Lỗi hay gặp: phủ định bằng 不曾经/没曾经; phải nói 没(有)…过.","en":"曾经: something happened at some time in the past and is over, usually with 过. 已经: something is done or has reached a point and still matters now, usually with 了. Common mistake: negating with 不曾经/没曾经; say 没(有)…过."},"examples":[{"zh":"我曾经在上海工作过两年。","py":"Wǒ céngjīng zài Shànghǎi gōngzuò guo liǎng nián.","vi":"Tôi đã từng làm việc ở Thượng Hải hai năm.","en":"I once worked in Shanghai for two years."},{"zh":"他已经在这家公司工作五年了。","py":"Tā yǐjīng zài zhè jiā gōngsī gōngzuò wǔ nián le.","vi":"Anh ấy đã làm việc ở công ty này năm năm rồi.","en":"He has already worked at this company for five years."}],"quiz":[{"q":"她____当过老师，现在是律师。","options":["正在","曾经","马上","一直"],"answer":1,"explain":{"vi":"Việc trong quá khứ nay đã hết, đi với 过, dùng 曾经.","en":"A past experience that is over, with 过, takes 曾经."}},{"q":"我____吃过饭了，你们吃吧。","options":["曾经","从来","仍然","已经"],"answer":3,"explain":{"vi":"Việc đã xong và liên quan đến hiện tại (có 了) dùng 已经.","en":"Something done and relevant now (with 了) takes 已经."}},{"q":"下面哪个句子是正确的？","options":["我没去过那个地方。","我没曾经去过那个地方。","我不曾经去那个地方。","我曾经没去那个地方过。"],"answer":0,"explain":{"vi":"Phủ định của 曾经…过 là 没(有)…过.","en":"The negative of 曾经…过 is 没(有)…过."}},{"q":"“他曾经住在北京”，他现在：","options":["还住在北京","刚到北京","不住在北京了","明天去北京"],"answer":2,"explain":{"vi":"曾经 cho biết việc đó nay đã kết thúc.","en":"曾经 tells us it is no longer the case."}},{"q":"我曾经学____一年日语，可是现在都忘了。","options":["着","过","的","得"],"answer":1,"explain":{"vi":"曾经 + động từ + 过.","en":"曾经 + verb + 过."}}]},
  {"id":"g51","title":{"zh":"刚 / 刚才","vi":"刚 (vừa mới) / 刚才 (lúc nãy)","en":"刚 / 刚才 (just / a moment ago)"},"pattern":"S + 刚 + V (+ duration) | 刚 + V1 + 就 + V2 | 刚才 + S + V  /  S + 刚才 + V | 刚才 + 的 + N","explain":{"vi":"刚 là phó từ, chỉ đứng sau chủ ngữ, nói việc xảy ra chưa lâu (theo cảm nhận người nói), sau động từ có thể có khoảng thời gian (刚来三天). 刚才 là danh từ chỉ thời gian \"lúc nãy\", đứng trước hoặc sau chủ ngữ, đi được với 不/没 và 的. Lỗi hay gặp: 刚才来三天, 刚没说.","en":"刚 is an adverb placed only after the subject; it says something happened not long ago (in the speaker's view) and may be followed by a duration (刚来三天). 刚才 is a time noun, \"a moment ago\"; it goes before or after the subject and works with 不/没 and 的. Common mistakes: 刚才来三天, 刚没说."},"examples":[{"zh":"我刚来公司三个月，很多事还不熟悉。","py":"Wǒ gāng lái gōngsī sān ge yuè, hěn duō shì hái bù shúxī.","vi":"Tôi mới vào công ty ba tháng, nhiều việc còn chưa quen.","en":"I joined the company only three months ago and many things are still unfamiliar."},{"zh":"刚才有人给你打电话，你不在。","py":"Gāngcái yǒu rén gěi nǐ dǎ diànhuà, nǐ bú zài.","vi":"Lúc nãy có người gọi điện cho bạn, bạn không có ở đây.","en":"Someone phoned you a moment ago, but you weren't here."}],"quiz":[{"q":"____的会议你为什么没参加？","options":["刚","曾经","刚才","已经"],"answer":2,"explain":{"vi":"Đứng trước 的 + danh từ phải là danh từ thời gian 刚才.","en":"Before 的 + noun you need the time noun 刚才."}},{"q":"他____到北京两天，还没有习惯这里的天气。","options":["刚才","刚","曾经","仍然"],"answer":1,"explain":{"vi":"Sau động từ có khoảng thời gian (两天) thì dùng 刚.","en":"With a duration after the verb (两天), use 刚."}},{"q":"你____为什么不说话？","options":["刚","从来","曾经","刚才"],"answer":3,"explain":{"vi":"Trước từ phủ định 不 dùng 刚才; 刚 không đi với phủ định.","en":"Before the negative 不 use 刚才; 刚 does not take a negative."}},{"q":"我____走出办公室，就下起雨来了。","options":["刚","刚才的","曾经","从来"],"answer":0,"explain":{"vi":"刚…就…: vừa… thì….","en":"刚…就… means \"no sooner… than…\"."}},{"q":"哪个词可以放在名词前面，比如“____的事”？","options":["只有“刚”","两个都可以","只有“刚才”","两个都不可以"],"answer":2,"explain":{"vi":"刚才 là danh từ thời gian nên có thể nói 刚才的事.","en":"刚才 is a time noun, so 刚才的事 is possible."}}]},
  {"id":"g52","title":{"zh":"才 / 就","vi":"才 (mới) / 就 (đã)","en":"才 / 就 (not until / as early as)"},"pattern":"time / amount + 就 + V + 了 (early, fast, easy) | time / amount + 才 + V (late, slow, hard)","explain":{"vi":"就: người nói thấy việc xảy ra sớm, nhanh, dễ; cuối câu thường có 了. 才: người nói thấy việc xảy ra muộn, chậm, khó; cuối câu không dùng 了. Lỗi hay gặp: thêm 了 sau 才 (他十点才来了 là sai).","en":"就: the speaker feels it happened early, fast or easily; 了 usually ends the sentence. 才: the speaker feels it happened late, slowly or with difficulty; no 了 at the end. Common mistake: adding 了 after 才 (他十点才来了 is wrong)."},"examples":[{"zh":"会议九点开始，他八点就到了。","py":"Huìyì jiǔ diǎn kāishǐ, tā bā diǎn jiù dào le.","vi":"Cuộc họp chín giờ bắt đầu, anh ấy tám giờ đã đến rồi.","en":"The meeting starts at nine, and he was already there at eight."},{"zh":"我昨天加班，晚上十一点才回家。","py":"Wǒ zuótiān jiābān, wǎnshang shíyī diǎn cái huí jiā.","vi":"Hôm qua tôi tăng ca, mười một giờ đêm mới về nhà.","en":"I worked overtime yesterday and didn't get home until eleven at night."}],"quiz":[{"q":"电影七点开始，他七点半____来。","options":["就","都","才","又"],"answer":2,"explain":{"vi":"Đến muộn hơn giờ bắt đầu dùng 才.","en":"Arriving later than the start takes 才."}},{"q":"这个问题很简单，他五分钟____做完了。","options":["才","就","再","还"],"answer":1,"explain":{"vi":"Làm nhanh, dễ, và cuối câu có 了 thì dùng 就.","en":"Done fast and easily, with 了 at the end, takes 就."}},{"q":"下面哪个句子是正确的？","options":["他昨天十二点才睡觉了。","他昨天才十二点睡觉了。","他才昨天十二点睡觉了。","他昨天十二点才睡觉。"],"answer":3,"explain":{"vi":"才 đứng sau thời gian, và cuối câu không có 了.","en":"才 follows the time, and there is no 了 at the end."}},{"q":"我找了三家商店____买到这本书。","options":["才","就","又","也"],"answer":0,"explain":{"vi":"Phải tìm nhiều nơi mới mua được, tức là khó, dùng 才.","en":"It took three shops, i.e. it was hard, so 才."}},{"q":"“他一个小时就写完了”，说话人觉得他写得：","options":["很慢","很差","很多","很快"],"answer":3,"explain":{"vi":"就 cho thấy người nói cảm thấy nhanh.","en":"就 shows the speaker finds it fast."}}]},
  {"id":"g53","title":{"zh":"再 / 又","vi":"再 (lại, nữa — chưa xảy ra) / 又 (lại — đã xảy ra)","en":"再 / 又 (again: not yet / already)"},"pattern":"S + 又 + V + 了 (repeated, already happened) | S + 再 + V (to be repeated) | 先 + V1，再 + V2 | 能愿动词 + 再 + V (想再看)","explain":{"vi":"又: việc lặp lại đã xảy ra rồi, thường có 了. 再: việc lặp lại chưa xảy ra, hoặc việc làm sau một việc khác (先…再…). 再 đứng sau 想/要/能. Lỗi hay gặp: 明天又来 (phải là 明天再来), 昨天再来了 (phải là 昨天又来了).","en":"又: the repetition has already happened, usually with 了. 再: the repetition has not happened yet, or one action follows another (先…再…). 再 goes after 想/要/能. Common mistakes: 明天又来 (say 明天再来), 昨天再来了 (say 昨天又来了)."},"examples":[{"zh":"他昨天迟到了，今天又迟到了。","py":"Tā zuótiān chídào le, jīntiān yòu chídào le.","vi":"Hôm qua anh ấy đến muộn, hôm nay lại đến muộn nữa.","en":"He was late yesterday, and he was late again today."},{"zh":"这个问题我没听懂，请您再说一遍。","py":"Zhège wèntí wǒ méi tīng dǒng, qǐng nín zài shuō yí biàn.","vi":"Câu hỏi này tôi nghe chưa hiểu, xin ông nói lại một lần nữa.","en":"I didn't understand the question; please say it once more."}],"quiz":[{"q":"欢迎你们明年____来！","options":["又","才","刚","再"],"answer":3,"explain":{"vi":"Việc lặp lại trong tương lai dùng 再.","en":"A repetition in the future takes 再."}},{"q":"你怎么____忘了带钥匙？上次也是这样。","options":["又","再","才","很"],"answer":0,"explain":{"vi":"Việc lặp lại đã xảy ra (忘了) dùng 又.","en":"A repetition that has already happened (忘了) takes 又."}},{"q":"这个电影太好看了，我想____看一遍。","options":["又","再","才","刚"],"answer":1,"explain":{"vi":"Sau 想, việc lặp lại chưa xảy ra dùng 再.","en":"After 想, a repetition not yet done takes 再."}},{"q":"下面哪个句子是正确的？","options":["我们先吃饭，吃完又讨论。","我们先吃饭，再吃完讨论了。","我们先吃饭，吃完再讨论。","我们又先吃饭，吃完讨论再。"],"answer":2,"explain":{"vi":"先…再…: làm việc này xong rồi mới làm việc kia.","en":"先…再…: do one thing first, then the other."}},{"q":"这个字我昨天写错了，今天____写错了。","options":["再","很","太","又"],"answer":3,"explain":{"vi":"Việc lặp lại đã xảy ra, có 了, dùng 又.","en":"The repetition already happened (with 了), so 又."}}]},
  {"id":"g54","title":{"zh":"却 / 倒","vi":"Phó từ chuyển ý 却 / 倒","en":"却 / 倒 (yet / contrary to what you'd think)"},"pattern":"…，S + 却 + V / Adj | …，S + 倒 + (挺 / 很) + Adj / V","explain":{"vi":"却: chỉ sự trái ngược với vế trước. 倒: trái với điều thường nghĩ, giọng nhẹ hơn, thường đi với ý tích cực. Cả hai là phó từ nên phải đứng sau chủ ngữ, trước động từ. Lỗi hay gặp: đặt 却 trước chủ ngữ như 但是 (却他没来 là sai).","en":"却 marks a contrast with what came before. 倒 marks something contrary to what one would assume, in a milder tone and often with a positive point. Both are adverbs, so they go after the subject and before the verb. Common mistake: placing 却 before the subject like 但是 (却他没来 is wrong)."},"examples":[{"zh":"他学了三年汉语，却不敢跟中国人说话。","py":"Tā xué le sān nián Hànyǔ, què bù gǎn gēn Zhōngguórén shuōhuà.","vi":"Anh ấy học tiếng Trung ba năm mà lại không dám nói chuyện với người Trung Quốc.","en":"He has studied Chinese for three years, yet he doesn't dare talk to Chinese people."},{"zh":"这家店不大，东西倒挺全的。","py":"Zhè jiā diàn bú dà, dōngxi dào tǐng quán de.","vi":"Cửa hàng này không lớn, nhưng đồ lại khá đầy đủ.","en":"This shop isn't big, but it is surprisingly well stocked."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["大家都同意，却他反对。","大家都同意，他却反对。","大家都同意，他反对却。","却大家都同意，他反对。"],"answer":1,"explain":{"vi":"却 là phó từ, đứng sau chủ ngữ 他.","en":"却 is an adverb and follows the subject 他."}},{"q":"我给他打了三次电话，他____一次也没接。","options":["就","才","再","却"],"answer":3,"explain":{"vi":"Kết quả trái với mong đợi dùng 却.","en":"A result contrary to what was hoped takes 却."}},{"q":"“却”应该放在句子的什么地方？","options":["主语前面","句子最后","主语后面、动词前面","宾语后面"],"answer":2,"explain":{"vi":"却 là phó từ: sau chủ ngữ, trước động từ.","en":"却 is an adverb: after the subject, before the verb."}},{"q":"房间不大，____很干净。","options":["倒","就","才","又"],"answer":0,"explain":{"vi":"Trái với điều thường nghĩ, mang ý tích cực, dùng 倒.","en":"A pleasant point contrary to what one might think takes 倒."}},{"q":"他平时话很少，开会的时候____说了很多。","options":["也","却","都","再"],"answer":1,"explain":{"vi":"Hai vế trái ngược nhau nên dùng 却.","en":"The two halves contrast, so 却."}}]},
  {"id":"g55","title":{"zh":"并 + 不 / 没","vi":"并 nhấn mạnh phủ định","en":"并 + 不 / 没 (not at all, actually not)"},"pattern":"S + 并 + 不 / 没 (有) + V / Adj","explain":{"vi":"Đặt 并 trước 不/没 để nhấn mạnh sự thật khác với điều người ta tưởng: \"thật ra không hề…\". Lỗi hay gặp: dùng 并 trong câu khẳng định (他并很忙 là sai); 并 chỉ đứng trước từ phủ định.","en":"并 before 不/没 stresses that the facts differ from what people assume: \"actually not…\". Common mistake: using 并 in an affirmative sentence (他并很忙 is wrong); it only goes before a negative."},"examples":[{"zh":"这份工作并不像你想的那么轻松。","py":"Zhè fèn gōngzuò bìng bú xiàng nǐ xiǎng de nàme qīngsōng.","vi":"Công việc này thật ra không nhẹ nhàng như bạn nghĩ đâu.","en":"This job is not actually as easy as you think."},{"zh":"我并没有说过这样的话。","py":"Wǒ bìng méiyǒu shuō guo zhèyàng de huà.","vi":"Tôi hoàn toàn chưa từng nói những lời như vậy.","en":"I never actually said such a thing."}],"quiz":[{"q":"大家都以为他很有钱，其实他____不富。","options":["就","再","刚","并"],"answer":3,"explain":{"vi":"并不: nhấn mạnh sự thật trái với điều mọi người tưởng.","en":"并不 stresses that the truth differs from what everyone thought."}},{"q":"下面哪个句子是正确的？","options":["这个办法并能解决问题。","这个办法不并能解决问题。","这个办法并不能解决问题。","并这个办法不能解决问题。"],"answer":2,"explain":{"vi":"并 đứng sau chủ ngữ và ngay trước 不.","en":"并 follows the subject and goes right before 不."}},{"q":"你误会了，我并____生你的气。","options":["很","没有","已经","一定"],"answer":1,"explain":{"vi":"Sau 并 phải là từ phủ định 不 hoặc 没(有).","en":"并 must be followed by the negative 不 or 没(有)."}},{"q":"“并不”“并没有”常常用来：","options":["说明事实和别人想的不一样","表示非常肯定","提出问题","表示两件事一起发生"],"answer":0,"explain":{"vi":"并 + phủ định dùng để bác bỏ một suy nghĩ có sẵn.","en":"并 + negative is used to correct an existing assumption."}},{"q":"价格高的东西，质量并____好。","options":["一定","不一定","非常","已经"],"answer":1,"explain":{"vi":"Sau 并 cần từ phủ định: 并不一定.","en":"并 needs a negative after it: 并不一定."}}]},
  {"id":"g56","title":{"zh":"概数的表达","vi":"Cách nói số ước lượng","en":"Approximate numbers (左右 / 大约 / 多 / 几)"},"pattern":"Num + MW + 左右 | 大约 / 大概 + Num | 10, 20, 100… + 多 + MW (二十多个) | 1–9 + MW + 多 + N (三个多月) | 两三 + MW","explain":{"vi":"左右 đứng sau số lượng; 大约/大概 đứng trước. 多 đứng trước lượng từ nếu số tròn chục, trăm (二十多个人), đứng sau lượng từ nếu là số lẻ 1–9 (三个多小时). Hai số liền nhau cũng chỉ ước lượng (两三天). Lỗi hay gặp: đặt sai vị trí của 多 (一多个小时 là sai).","en":"左右 follows the quantity; 大约/大概 precede it. 多 goes before the measure word after round tens or hundreds (二十多个人) and after the measure word with 1–9 (三个多小时). Two adjacent numbers also give an estimate (两三天). Common mistake: misplacing 多 (一多个小时 is wrong)."},"examples":[{"zh":"今天的会议大约需要两个小时。","py":"Jīntiān de huìyì dàyuē xūyào liǎng ge xiǎoshí.","vi":"Cuộc họp hôm nay cần khoảng hai tiếng.","en":"Today's meeting will take about two hours."},{"zh":"我们公司有三百多个员工。","py":"Wǒmen gōngsī yǒu sānbǎi duō ge yuángōng.","vi":"Công ty chúng tôi có hơn ba trăm nhân viên.","en":"Our company has over three hundred employees."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["我等了他一个多小时。","我等了他一多个小时。","我等了他多一个小时。","我等了他一个小时多左右。"],"answer":0,"explain":{"vi":"Với số 1–9, 多 đứng sau lượng từ: 一个多小时.","en":"With 1–9, 多 follows the measure word: 一个多小时."}},{"q":"这个班有二十____个学生。","options":["左右","大约","几乎","多"],"answer":3,"explain":{"vi":"Với số tròn chục, 多 đứng trước lượng từ: 二十多个.","en":"After a round ten, 多 goes before the measure word: 二十多个."}},{"q":"他每个月的收入在八千块____。","options":["大约","左右","多么","几个"],"answer":1,"explain":{"vi":"左右 đứng sau số lượng.","en":"左右 follows the quantity."}},{"q":"“我两三天就回来”的意思是：","options":["两天或者三天就回来","二十三天就回来","两天以后再过三天回来","第二天和第三天都回来"],"answer":0,"explain":{"vi":"Hai số liền nhau chỉ số ước lượng.","en":"Two adjacent numbers give an approximate amount."}},{"q":"从这儿到机场____要四十分钟。","options":["左右","多","来","大约"],"answer":3,"explain":{"vi":"大约 đứng trước động từ hoặc số lượng.","en":"大约 goes before the verb or the quantity."}}]},
  {"id":"g57","title":{"zh":"动词重叠","vi":"Lặp lại động từ","en":"Verb reduplication"},"pattern":"AA / A一A (看看, 看一看) | A了A (看了看, done) | ABAB (休息休息, 讨论讨论)","explain":{"vi":"Lặp động từ để chỉ hành động ngắn, nhẹ nhàng hoặc làm thử, giọng thân mật. Việc đã xảy ra dùng A了A. Động từ hai âm tiết lặp theo kiểu ABAB, không chen 一. Lỗi hay gặp: dùng với 正在/着/过 hoặc nói 看看了, 休休息息.","en":"Reduplicating a verb marks a short, light or tentative action in a casual tone. For a completed action use A了A. Two-syllable verbs take ABAB with no 一. Common mistakes: using it with 正在/着/过, or saying 看看了, 休休息息."},"examples":[{"zh":"这个问题我们下午再讨论讨论吧。","py":"Zhège wèntí wǒmen xiàwǔ zài tǎolùn tǎolùn ba.","vi":"Vấn đề này buổi chiều chúng ta thảo luận thêm chút nhé.","en":"Let's discuss this issue a bit more this afternoon."},{"zh":"他看了看手表，说时间不早了。","py":"Tā kàn le kàn shǒubiǎo, shuō shíjiān bù zǎo le.","vi":"Anh ấy nhìn đồng hồ một cái rồi nói không còn sớm nữa.","en":"He glanced at his watch and said it was getting late."}],"quiz":[{"q":"你太累了，应该好好儿____。","options":["休休息息","休息一休息","休息着","休息休息"],"answer":3,"explain":{"vi":"Động từ hai âm tiết lặp theo kiểu ABAB.","en":"Two-syllable verbs reduplicate as ABAB."}},{"q":"下面哪个句子是正确的？","options":["他笑了笑，没有回答。","他笑笑了，没有回答。","他笑一笑了，没有回答。","他正在笑笑，没有回答。"],"answer":0,"explain":{"vi":"Việc đã xảy ra dùng A了A; không dùng với 正在.","en":"A completed action takes A了A; it cannot combine with 正在."}},{"q":"这件衣服很漂亮，你____吧。","options":["试着","试过","试试","试了"],"answer":2,"explain":{"vi":"Làm thử một chút dùng động từ lặp lại.","en":"Trying something out takes the reduplicated verb."}},{"q":"我正在____电视，你等一下。","options":["看看","看一看","看了看","看"],"answer":3,"explain":{"vi":"Sau 正在 không dùng động từ lặp lại.","en":"A reduplicated verb cannot follow 正在."}},{"q":"这是我的计划，请您____。","options":["看一看","看看一","一看看","看了一"],"answer":0,"explain":{"vi":"Động từ một âm tiết có thể dùng A一A.","en":"One-syllable verbs can take A一A."}}]},
  {"id":"g58","title":{"zh":"形容词重叠","vi":"Lặp lại tính từ","en":"Adjective reduplication"},"pattern":"AA + 的 (大大的) | AABB + 的 (干干净净的) | AA / AABB + 地 + V","explain":{"vi":"Lặp tính từ để miêu tả sinh động hoặc tăng mức độ. Tính từ một âm tiết: AA; hai âm tiết: AABB. Sau đó thường có 的 (làm vị ngữ, định ngữ) hoặc 地 (làm trạng ngữ). Lỗi hay gặp: thêm 很/非常 phía trước (很大大的 là sai), hoặc lặp kiểu ABAB như động từ.","en":"Reduplicating an adjective makes the description vivid or stronger. One syllable: AA; two syllables: AABB. It is usually followed by 的 (as predicate or modifier) or 地 (before a verb). Common mistakes: adding 很/非常 in front (很大大的 is wrong), or using the verb pattern ABAB."},"examples":[{"zh":"她把办公室打扫得干干净净的。","py":"Tā bǎ bàngōngshì dǎsǎo de gāngānjìngjìng de.","vi":"Cô ấy quét dọn văn phòng sạch sẽ tinh tươm.","en":"She cleaned the office until it was spotless."},{"zh":"你慢慢地说，我们都在认真听。","py":"Nǐ mànmàn de shuō, wǒmen dōu zài rènzhēn tīng.","vi":"Bạn cứ nói từ từ, chúng tôi đều đang chăm chú nghe.","en":"Take your time; we are all listening carefully."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["她的眼睛很大大的。","她的眼睛大大很。","她的眼睛非常大大的。","她的眼睛大大的。"],"answer":3,"explain":{"vi":"Tính từ lặp lại không thêm 很/非常, và sau nó có 的.","en":"A reduplicated adjective takes no 很/非常 and is followed by 的."}},{"q":"孩子们____地回家了。","options":["高高兴兴","高兴高兴","很高高兴兴","高高兴"],"answer":0,"explain":{"vi":"Tính từ hai âm tiết lặp theo kiểu AABB.","en":"Two-syllable adjectives reduplicate as AABB."}},{"q":"“干净”的重叠形式是：","options":["干净干净","干干净净","干干净","干净净"],"answer":1,"explain":{"vi":"Tính từ hai âm tiết: AABB.","en":"Two-syllable adjective: AABB."}},{"q":"他____地坐在那儿，一句话也不说。","options":["安静安静","很安安静静","安静静","安安静静"],"answer":3,"explain":{"vi":"AABB + 地 + động từ.","en":"AABB + 地 + verb."}},{"q":"形容词重叠以后，前面不能再加哪个词？","options":["很","也","都","就"],"answer":0,"explain":{"vi":"Tính từ lặp lại đã mang nghĩa mức độ nên không thêm 很.","en":"A reduplicated adjective already expresses degree, so 很 cannot be added."}}]},
  {"id":"g59","title":{"zh":"存现句","vi":"Câu tồn hiện","en":"Existential sentences"},"pattern":"Place + V + 着 + Num + MW + N (something is there) | Place + V + 了 / 来 / 走 + Num + MW + N (appears / disappears)","explain":{"vi":"Nói ở đâu đó có, xuất hiện hoặc mất đi người/vật. Từ chỉ nơi chốn đứng đầu câu và thường không có 在; người/vật đứng sau động từ và là không xác định (一个, 几份). Lỗi hay gặp: theo trật tự tiếng Việt đặt người/vật ở đầu câu (两个人站着门口 là sai).","en":"Says that something exists, appears or disappears somewhere. The place word opens the sentence, usually without 在; the person or thing follows the verb and is indefinite (一个, 几份). Common mistake: putting the person or thing first (两个人站着门口 is wrong)."},"examples":[{"zh":"会议室的桌子上放着几份材料。","py":"Huìyìshì de zhuōzi shang fàng zhe jǐ fèn cáiliào.","vi":"Trên bàn phòng họp có để mấy bản tài liệu.","en":"There are a few documents lying on the meeting-room table."},{"zh":"我们办公室来了一位新同事。","py":"Wǒmen bàngōngshì lái le yí wèi xīn tóngshì.","vi":"Văn phòng chúng tôi vừa có một đồng nghiệp mới đến.","en":"A new colleague has joined our office."}],"quiz":[{"q":"教室里____一张中国地图。","options":["挂在","在挂","挂得","挂着"],"answer":3,"explain":{"vi":"Nơi chốn + động từ + 着 + vật: chỉ sự tồn tại.","en":"Place + verb + 着 + thing shows existence."}},{"q":"下面哪个句子是正确的？","options":["两个人站着门口。","门口站着两个人。","门口两个人站着在。","在门口站两个人着。"],"answer":1,"explain":{"vi":"Nơi chốn đứng đầu câu, người đứng sau động từ + 着.","en":"The place comes first and the people follow verb + 着."}},{"q":"前面开____一辆出租车。","options":["来","在","着了","得"],"answer":0,"explain":{"vi":"Nơi chốn + động từ + 来 + vật: chỉ sự xuất hiện.","en":"Place + verb + 来 + thing shows appearance."}},{"q":"下面哪个句子是正确的？","options":["桌子上在放一本词典。","一本词典放着桌子上。","桌子放着一本词典上。","桌子上放着一本词典。"],"answer":3,"explain":{"vi":"Trật tự: nơi chốn (có 上) + 放着 + số lượng + vật.","en":"Order: place (with 上) + 放着 + quantity + thing."}},{"q":"昨天我们楼里____一家人。","options":["搬走着","在搬走","搬走了","搬走得"],"answer":2,"explain":{"vi":"Nơi chốn + động từ + 走了 + người: chỉ sự mất đi.","en":"Place + verb + 走了 + people shows disappearance."}}]},
  {"id":"g60","title":{"zh":"兼语句","vi":"Câu kiêm ngữ (让 / 叫 / 请 / 使)","en":"Pivotal sentences (让 / 叫 / 请 / 使)"},"pattern":"S + 让 / 叫 / 请 / 使 + person + V (+ O) | S + 不 / 没 + 让 / 请 + person + V","explain":{"vi":"Chủ ngữ bảo, mời hoặc khiến người khác làm gì; người đó vừa là tân ngữ của động từ thứ nhất, vừa là chủ thể của động từ thứ hai. 使 chủ yếu chỉ gây ra cảm xúc, thay đổi. Lỗi hay gặp: đặt 不/没 trước động từ thứ hai để phủ định cả câu; phủ định phải đứng trước 让/叫/请.","en":"The subject tells, invites or causes someone to do something; that person is the object of the first verb and the doer of the second. 使 mainly causes a feeling or change. Common mistake: putting 不/没 before the second verb to negate the whole sentence; the negative goes before 让/叫/请."},"examples":[{"zh":"经理让我明天去机场接客人。","py":"Jīnglǐ ràng wǒ míngtiān qù jīchǎng jiē kèrén.","vi":"Giám đốc bảo tôi ngày mai ra sân bay đón khách.","en":"The manager asked me to pick up the visitors at the airport tomorrow."},{"zh":"公司请了一位律师来给大家讲课。","py":"Gōngsī qǐng le yí wèi lǜshī lái gěi dàjiā jiǎngkè.","vi":"Công ty đã mời một luật sư đến giảng bài cho mọi người.","en":"The company invited a lawyer to give everyone a talk."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["经理让我写一份总结。","经理让写我一份总结。","经理我让写一份总结。","经理让我一份总结写。"],"answer":0,"explain":{"vi":"Trật tự: 让 + người + động từ + tân ngữ.","en":"Order: 让 + person + verb + object."}},{"q":"妈妈不____我一个人去旅行。","options":["把","被","对","让"],"answer":3,"explain":{"vi":"不让 + người + động từ: không cho ai làm gì.","en":"不让 + person + verb: not let someone do something."}},{"q":"下面哪个句子是正确的？","options":["他请没我参加他的生日聚会。","他没请我参加他的生日聚会。","他请我参加没他的生日聚会。","他请我没参加他的生日聚会。"],"answer":1,"explain":{"vi":"Từ phủ định 没 đứng trước động từ thứ nhất 请.","en":"The negative 没 goes before the first verb 请."}},{"q":"这个消息____大家非常高兴。","options":["把","被","使","对"],"answer":2,"explain":{"vi":"使 + người + cảm xúc: khiến ai thế nào.","en":"使 + person + feeling: make someone feel something."}},{"q":"“王经理叫小李去银行”，去银行的人是：","options":["小李","王经理","两个人一起","别的同事"],"answer":0,"explain":{"vi":"Người đứng sau 叫 là người thực hiện động từ thứ hai.","en":"The person after 叫 does the second action."}}]},
  {"id":"g61","title":{"zh":"连动句","vi":"Câu liên động","en":"Serial verb sentences"},"pattern":"S + V1 (+ O1) + V2 (+ O2) | 去 / 来 + place + V (purpose) | 坐 / 骑 / 用 + N + V (means)","explain":{"vi":"Một chủ ngữ làm hai hành động liên tiếp; thứ tự cố định: phương tiện/cách thức đứng trước, mục đích đứng sau. 不/没 và trợ động từ đứng trước động từ thứ nhất. Lỗi hay gặp: theo trật tự tiếng Việt \"đi làm bằng tàu điện\" mà nói 上班坐地铁; phải nói 坐地铁上班.","en":"One subject performs two linked actions in a fixed order: means or manner first, purpose after. 不/没 and modal verbs go before the first verb. Common mistake: following Vietnamese order (\"go to work by metro\") and saying 上班坐地铁; say 坐地铁上班."},"examples":[{"zh":"我每天坐地铁去公司上班。","py":"Wǒ měi tiān zuò dìtiě qù gōngsī shàngbān.","vi":"Ngày nào tôi cũng đi tàu điện ngầm đến công ty làm việc.","en":"I take the metro to work every day."},{"zh":"他下午要去银行办一张信用卡。","py":"Tā xiàwǔ yào qù yínháng bàn yì zhāng xìnyòngkǎ.","vi":"Buổi chiều anh ấy phải ra ngân hàng làm một thẻ tín dụng.","en":"This afternoon he is going to the bank to apply for a credit card."}],"quiz":[{"q":"下面哪个句子是正确的？","options":["我给他发了一条短信用手机。","我发了用手机一条短信给他。","我用手机给他发了一条短信。","我给他用发了手机一条短信。"],"answer":2,"explain":{"vi":"Phương tiện (用手机) đứng trước hành động chính.","en":"The means (用手机) comes before the main action."}},{"q":"下面哪个句子是正确的？","options":["他去图书馆借了两本书。","他借去图书馆了两本书。","他图书馆去借了两本书。","他去借图书馆了两本书。"],"answer":0,"explain":{"vi":"去 + nơi chốn + động từ chỉ mục đích; 了 đứng sau động từ thứ hai.","en":"去 + place + purpose verb; 了 follows the second verb."}},{"q":"我明天____飞机去上海出差。","options":["在","从","往","坐"],"answer":3,"explain":{"vi":"坐 + phương tiện + 去 + nơi chốn.","en":"坐 + vehicle + 去 + place."}},{"q":"下面哪个句子是正确的？","options":["我今天去不超市买东西。","我今天不去超市买东西。","我今天去超市买不东西。","我不今天去超市买东西。"],"answer":1,"explain":{"vi":"不 đứng trước động từ thứ nhất 去.","en":"不 goes before the first verb 去."}},{"q":"“她骑自行车去上班”中，“骑自行车”表示：","options":["去上班的原因","去上班的时间","去上班的结果","去上班的方式"],"answer":3,"explain":{"vi":"Động từ thứ nhất chỉ phương tiện, cách thức.","en":"The first verb gives the means or manner."}}]},
  {"id":"g62","title":{"zh":"对……来说","vi":"Đối với… mà nói","en":"对…来说 (for…, as far as… is concerned)"},"pattern":"对 + person / group + 来说，+ judgement | S + 对 + person + 来说 + Adj","explain":{"vi":"Nêu người hoặc nhóm người mà nhận xét phía sau áp dụng cho họ. Có thể đứng đầu câu hoặc sau chủ ngữ. Lỗi hay gặp: bỏ 来说 hoặc đảo thành 说来 (对我说 có nghĩa khác: \"nói với tôi\").","en":"Names the person or group for whom the following judgement holds. It can open the sentence or follow the subject. Common mistake: dropping 来说 or reversing it (对我说 means something else: \"say to me\")."},"examples":[{"zh":"对我来说，这是一个很好的机会。","py":"Duì wǒ lái shuō, zhè shì yí ge hěn hǎo de jīhuì.","vi":"Đối với tôi, đây là một cơ hội rất tốt.","en":"For me, this is a very good opportunity."},{"zh":"对新员工来说，熟悉环境需要时间。","py":"Duì xīn yuángōng lái shuō, shúxī huánjìng xūyào shíjiān.","vi":"Đối với nhân viên mới, làm quen môi trường cần có thời gian.","en":"For new employees, getting used to the environment takes time."}],"quiz":[{"q":"____外国人来说，汉字是最难的。","options":["从","向","跟","对"],"answer":3,"explain":{"vi":"对…来说: đối với… mà nói.","en":"对…来说: as far as … is concerned."}},{"q":"对孩子____，玩儿也是一种学习。","options":["来说","来看","起来","下去"],"answer":0,"explain":{"vi":"Cấu trúc cố định là 对…来说.","en":"The fixed pattern is 对…来说."}},{"q":"下面哪个句子是正确的？","options":["我对来说，健康比钱更重要。","对来说我，健康比钱更重要。","对我来说，健康比钱更重要。","对我说来健康，比钱更重要。"],"answer":2,"explain":{"vi":"对 + người + 来说 đứng đầu câu, sau đó là nhận xét.","en":"对 + person + 来说 opens the sentence, then comes the judgement."}},{"q":"这个价格____学生来说太贵了。","options":["把","对","被","给"],"answer":1,"explain":{"vi":"Sau chủ ngữ cũng dùng 对…来说.","en":"对…来说 can also follow the subject."}},{"q":"“对他来说，这不算什么”的意思是：","options":["他觉得这不是大问题","他不会算","他什么都不说","他不想来"],"answer":0,"explain":{"vi":"对他来说 = đối với anh ấy; 不算什么 = không đáng kể.","en":"对他来说 = for him; 不算什么 = it is nothing much."}}]},
  {"id":"g63","title":{"zh":"在……上 / 中 / 下 / 方面","vi":"Cấu trúc 在…上 / 中 / 下 / 方面","en":"在…上 / 中 / 下 / 方面 (in terms of / during / under)"},"pattern":"在 + N + 上 (aspect: 工作上, 生活上) | 在 + process + 中 (in the course of) | 在 + N + 的 + 帮助 / 支持 / 影响 + 下 (condition) | 在 + N + 方面","explain":{"vi":"在…上/方面: về mặt nào đó. 在…中: trong quá trình. 在…下: dưới điều kiện, sự tác động nào đó, ở giữa thường là \"的 + 帮助/支持/影响/要求\". Lỗi hay gặp: dùng 在…上 cho điều kiện (在老师的帮助上 là sai, phải là 在老师的帮助下).","en":"在…上/方面: in a certain respect. 在…中: in the course of something. 在…下: under some condition or influence, usually with \"的 + 帮助/支持/影响/要求\" inside. Common mistake: using 在…上 for a condition (在老师的帮助上 is wrong; say 在老师的帮助下)."},"examples":[{"zh":"在同事的帮助下，我很快熟悉了工作。","py":"Zài tóngshì de bāngzhù xià, wǒ hěn kuài shúxī le gōngzuò.","vi":"Nhờ sự giúp đỡ của đồng nghiệp, tôi đã nhanh chóng quen việc.","en":"With my colleagues' help I quickly got used to the work."},{"zh":"他在工作上非常认真，从来不马虎。","py":"Tā zài gōngzuò shang fēicháng rènzhēn, cónglái bù mǎhu.","vi":"Trong công việc anh ấy rất nghiêm túc, không bao giờ cẩu thả.","en":"He is very serious about his work and never careless."}],"quiz":[{"q":"在大家的支持____，活动办得很成功。","options":["上","中","里","下"],"answer":3,"explain":{"vi":"在…的支持下: dưới sự ủng hộ của….","en":"在…的支持下: with the support of…."}},{"q":"在讨论____，大家提出了很多好意见。","options":["中","下","边","外"],"answer":0,"explain":{"vi":"在…中: trong quá trình (thảo luận).","en":"在…中: in the course of (the discussion)."}},{"q":"她在管理____很有经验。","options":["下","方面","以外","左右"],"answer":1,"explain":{"vi":"在…方面: về mặt….","en":"在…方面: in the area of…."}},{"q":"在生活____，他是一个很随便的人。","options":["下","前","上","后"],"answer":2,"explain":{"vi":"在生活上: về mặt sinh hoạt, đời sống.","en":"在生活上: in daily life."}},{"q":"下面哪个句子是正确的？","options":["在父母的影响下，他爱上了音乐。","在影响父母下，他爱上了音乐。","父母的影响在下，他爱上了音乐。","在下父母的影响，他爱上了音乐。"],"answer":0,"explain":{"vi":"在 + người + 的 + 影响 + 下.","en":"在 + person + 的 + 影响 + 下."}}]},
  {"id":"g64","title":{"zh":"以为 / 认为","vi":"以为 (tưởng là) / 认为 (cho rằng)","en":"以为 / 认为 (thought wrongly / think that)"},"pattern":"S + 认为 + clause (opinion) | S + 以为 + clause，原来 / 其实 / 没想到 / 结果…","explain":{"vi":"认为: nêu quan điểm, nhận định của mình. 以为: đã tưởng như vậy nhưng thực tế không phải, phía sau thường có 原来, 其实, 没想到. Lỗi hay gặp: dùng 以为 để nêu ý kiến (我以为这个计划很好 dễ bị hiểu là \"tôi đã tưởng… nhưng sai\").","en":"认为 states one's view or judgement. 以为 means one believed something that turned out untrue, often followed by 原来, 其实, 没想到. Common mistake: using 以为 to give an opinion (我以为这个计划很好 sounds like \"I thought so, but I was wrong\")."},"examples":[{"zh":"我以为今天是星期五，原来是星期四。","py":"Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīsì.","vi":"Tôi cứ tưởng hôm nay là thứ Sáu, hóa ra là thứ Năm.","en":"I thought today was Friday, but it turns out it's Thursday."},{"zh":"我认为这个计划还需要再讨论一下。","py":"Wǒ rènwéi zhège jìhuà hái xūyào zài tǎolùn yíxià.","vi":"Tôi cho rằng kế hoạch này còn cần thảo luận thêm.","en":"I think this plan needs a little more discussion."}],"quiz":[{"q":"我____他是中国人，没想到他是日本人。","options":["认为","认识","知道","以为"],"answer":3,"explain":{"vi":"Tưởng sai, phía sau có 没想到, dùng 以为.","en":"A mistaken belief, followed by 没想到, takes 以为."}},{"q":"医生们____，这种方法是安全的。","options":["认为","以为","认识","作为"],"answer":0,"explain":{"vi":"Nêu nhận định, quan điểm dùng 认为.","en":"Stating a judgement takes 认为."}},{"q":"“我以为你不来了”说明：","options":["你没来","你来了","我不想让你来","我知道你会来"],"answer":1,"explain":{"vi":"以为 cho thấy điều đã tưởng là sai: thực tế là bạn đã đến.","en":"以为 shows the belief was wrong: you did come."}},{"q":"你____这个问题应该怎么解决？","options":["以为","因为","认为","作为"],"answer":2,"explain":{"vi":"Hỏi ý kiến người khác dùng 认为.","en":"Asking for someone's opinion takes 认为."}},{"q":"他一直____会议是三点开始，结果迟到了一个小时。","options":["希望","打算","决定","以为"],"answer":3,"explain":{"vi":"Tưởng sai giờ họp nên đến muộn, dùng 以为.","en":"He was wrong about the time and came late, so 以为."}}]},
  {"id":"g65","title":{"zh":"不得不 / 只好","vi":"不得不 / 只好 (đành phải, buộc phải)","en":"不得不 / 只好 (have no choice but to)"},"pattern":"S + 不得不 + V | S + 只好 + V","explain":{"vi":"Vì hoàn cảnh nên không còn cách nào khác, phải làm một việc mình không muốn. Lỗi hay gặp: hiểu 不得不 là \"không được làm\"; thật ra hai lần phủ định thành khẳng định: 不得不去 = buộc phải đi.","en":"Circumstances leave no other option, so one has to do something unwanted. Common mistake: reading 不得不 as \"must not\"; the double negative makes a positive: 不得不去 = have to go."},"examples":[{"zh":"最后一班地铁已经走了，我们只好打车。","py":"Zuìhòu yì bān dìtiě yǐjīng zǒu le, wǒmen zhǐhǎo dǎchē.","vi":"Chuyến tàu điện ngầm cuối cùng đã đi rồi, chúng tôi đành phải gọi taxi.","en":"The last metro had gone, so we had to take a taxi."},{"zh":"因为身体不好，他不得不提前回家休息。","py":"Yīnwèi shēntǐ bù hǎo, tā bùdébù tíqián huí jiā xiūxi.","vi":"Vì sức khỏe không tốt, anh ấy buộc phải về nhà nghỉ sớm.","en":"Because he was unwell, he had to go home early to rest."}],"quiz":[{"q":"“我不得不去”的意思是：","options":["我必须去","我不能去","我不想去，所以没去","我去不了"],"answer":0,"explain":{"vi":"不得不 = buộc phải.","en":"不得不 = have to."}},{"q":"雨太大了，比赛____推迟。","options":["来不及","差不多","不得不","对不起"],"answer":2,"explain":{"vi":"Vì mưa to nên buộc phải hoãn.","en":"The heavy rain forces a postponement."}},{"q":"商店都关门了，我____明天再来买。","options":["正好","好像","从来","只好"],"answer":3,"explain":{"vi":"Không còn cách khác, đành phải… dùng 只好.","en":"With no other option, use 只好."}},{"q":"下面哪个句子是正确的？","options":["电梯坏了，我们走上去只好。","电梯坏了，我们只好走上去。","电梯坏了，我们走只好上去。","电梯坏了，我们只走好上去。"],"answer":1,"explain":{"vi":"只好 đứng trước cả cụm động từ.","en":"只好 goes before the whole verb phrase."}},{"q":"他不想加班，可是工作太多，____加班。","options":["不一定","不用","不如","不得不"],"answer":3,"explain":{"vi":"Không muốn nhưng buộc phải làm dùng 不得不.","en":"Unwilling but forced to: 不得不."}}]},
  {"id":"g66","title":{"zh":"的 / 地 / 得","vi":"Ba trợ từ kết cấu 的 / 地 / 得","en":"The three \"de\": 的 / 地 / 得"},"pattern":"modifier + 的 + N | manner + 地 + V | V / Adj + 得 + complement","explain":{"vi":"Ba chữ đều đọc \"de\". 的 đứng trước danh từ; 地 đứng trước động từ, sau từ chỉ cách thức; 得 đứng sau động từ/tính từ, trước bổ ngữ chỉ mức độ, kết quả. Lỗi hay gặp: viết 的 cho cả ba trường hợp; hãy nhìn từ đứng sau nó.","en":"All three are read \"de\". 的 comes before a noun; 地 comes before a verb, after a manner word; 得 comes after a verb or adjective, before a complement of degree or result. Common mistake: writing 的 for all three; look at what follows."},"examples":[{"zh":"他认真地检查了每一份材料。","py":"Tā rènzhēn de jiǎnchá le měi yí fèn cáiliào.","vi":"Anh ấy đã kiểm tra cẩn thận từng bản tài liệu.","en":"He carefully checked every document."},{"zh":"她汉语说得很流利，写的字也很漂亮。","py":"Tā Hànyǔ shuō de hěn liúlì, xiě de zì yě hěn piàoliang.","vi":"Cô ấy nói tiếng Trung rất lưu loát, chữ viết cũng rất đẹp.","en":"She speaks Chinese fluently, and her handwriting is beautiful too."}],"quiz":[{"q":"他们热情____欢迎我们。","options":["的","得","了","地"],"answer":3,"explain":{"vi":"Từ chỉ cách thức + 地 + động từ (欢迎).","en":"Manner word + 地 + verb (欢迎)."}},{"q":"他跑____很快。","options":["得","的","地","着"],"answer":0,"explain":{"vi":"Động từ + 得 + bổ ngữ mức độ.","en":"Verb + 得 + degree complement."}},{"q":"这是我新买____手机。","options":["地","的","得","着"],"answer":1,"explain":{"vi":"Định ngữ + 的 + danh từ (手机).","en":"Modifier + 的 + noun (手机)."}},{"q":"下面哪个句子是正确的？","options":["她高兴的告诉我，她考地很好。","她高兴得告诉我，她考的很好。","她高兴地告诉我，她考得很好。","她高兴地告诉我，她考的很好。"],"answer":2,"explain":{"vi":"Trước động từ 告诉 dùng 地; sau động từ 考 dùng 得.","en":"Before the verb 告诉 use 地; after the verb 考 use 得."}},{"q":"今天忙____连饭都没吃。","options":["得","的","地","了"],"answer":0,"explain":{"vi":"Tính từ + 得 + bổ ngữ chỉ kết quả, mức độ.","en":"Adjective + 得 + complement of result or degree."}}]},
  {"id":"g67","title":{"zh":"本来 / 原来","vi":"本来 (vốn dĩ) / 原来 (ban đầu; hóa ra)","en":"本来 / 原来 (originally / it turns out)"},"pattern":"S + 本来 + plan / state，可是 / 后来… (it changed) | 本来 + 就 + … (as it should be) | 原来 + newly discovered fact","explain":{"vi":"本来: tình hình lúc đầu, về sau đã thay đổi; 本来就 = lẽ ra vốn phải thế. 原来 cũng có nghĩa \"ban đầu\", nhưng còn dùng khi vừa phát hiện ra sự thật: \"hóa ra\". Lỗi hay gặp: dùng 本来 với nghĩa \"hóa ra\" (本来是你！ là sai, phải nói 原来是你！).","en":"本来: how things were at first before they changed; 本来就 = as it should be anyway. 原来 can also mean \"originally\", but it is the one used on discovering a fact: \"so it turns out\". Common mistake: using 本来 for \"it turns out\" (本来是你！ is wrong; say 原来是你！)."},"examples":[{"zh":"我本来想请假，后来还是去上班了。","py":"Wǒ běnlái xiǎng qǐngjià, hòulái háishi qù shàngbān le.","vi":"Tôi vốn định xin nghỉ, sau đó vẫn đi làm.","en":"I was going to ask for leave, but in the end I went to work anyway."},{"zh":"原来你们早就认识，我还想给你们介绍呢。","py":"Yuánlái nǐmen zǎo jiù rènshi, wǒ hái xiǎng gěi nǐmen jièshào ne.","vi":"Hóa ra các bạn quen nhau từ lâu rồi, tôi còn định giới thiệu cho các bạn nữa.","en":"So you two already know each other; I was about to introduce you."}],"quiz":[{"q":"办公室怎么这么冷？啊，____窗户没关。","options":["本来","从来","后来","原来"],"answer":3,"explain":{"vi":"Vừa phát hiện ra nguyên nhân: \"hóa ra\" dùng 原来.","en":"Just discovering the reason, \"so it turns out\", takes 原来."}},{"q":"这件事____就应该由你负责。","options":["本来","后来","从来","将来"],"answer":0,"explain":{"vi":"本来就: vốn dĩ đã phải như vậy.","en":"本来就: that is how it should be anyway."}},{"q":"我____打算周末去爬山，可是下雨了。","options":["后来","本来","果然","竟然"],"answer":1,"explain":{"vi":"Dự định ban đầu, sau đó thay đổi, dùng 本来.","en":"An original plan that then changed takes 本来."}},{"q":"“原来是你！”这句话说明说话人：","options":["早就知道是你","不认识你","刚刚才知道是你","不希望是你"],"answer":2,"explain":{"vi":"原来 ở đây chỉ việc vừa mới phát hiện ra.","en":"Here 原来 marks something just discovered."}},{"q":"我找了半天钥匙，____它就在我的包里。","options":["从来","后来","将来","原来"],"answer":3,"explain":{"vi":"Phát hiện ra sự thật sau khi tìm: 原来.","en":"Finding out the truth after searching: 原来."}}]},
  {"id":"g68","title":{"zh":"一点儿 / 有点儿","vi":"一点儿 / 有点儿 (một chút / hơi)","en":"一点儿 / 有点儿 (a bit / a bit too)"},"pattern":"有点儿 + Adj / V (slightly, usually unwelcome) | Adj + 一点儿 (comparison, request) | V + 一点儿 + N | 一点儿 + 也 / 都 + 不 / 没…","explain":{"vi":"有点儿 đứng trước tính từ, thường nói điều không như ý (有点儿贵). 一点儿 đứng sau tính từ để so sánh hoặc yêu cầu (便宜一点儿), hoặc đứng trước danh từ chỉ lượng ít (喝一点儿水). Lỗi hay gặp: theo tiếng Việt \"một chút mệt\" nói 一点儿累; phải nói 有点儿累.","en":"有点儿 goes before an adjective, usually for something unwelcome (有点儿贵). 一点儿 goes after an adjective for comparison or a request (便宜一点儿), or before a noun for a small amount (喝一点儿水). Common mistake: saying 一点儿累 for \"a bit tired\"; say 有点儿累."},"examples":[{"zh":"今天有点儿冷，你多穿一点儿衣服。","py":"Jīntiān yǒudiǎnr lěng, nǐ duō chuān yìdiǎnr yīfu.","vi":"Hôm nay hơi lạnh, bạn mặc thêm chút áo vào.","en":"It's a bit cold today; put on some more clothes."},{"zh":"这个价格有点儿高，能便宜一点儿吗？","py":"Zhège jiàgé yǒudiǎnr gāo, néng piányi yìdiǎnr ma?","vi":"Giá này hơi cao, có thể rẻ hơn một chút không?","en":"This price is a bit high; could it be a little cheaper?"}],"quiz":[{"q":"我今天____累，想早点儿休息。","options":["一点儿","一下儿","一会儿","有点儿"],"answer":3,"explain":{"vi":"Trước tính từ, chỉ điều không như ý, dùng 有点儿.","en":"Before an adjective, for something unwelcome, use 有点儿."}},{"q":"请你说得慢____。","options":["一点儿","有点儿","一共","一起"],"answer":0,"explain":{"vi":"Tính từ + 一点儿 dùng khi yêu cầu.","en":"Adjective + 一点儿 is used in requests."}},{"q":"这件事我____也不知道。","options":["有点儿","一下","一点儿","一边"],"answer":2,"explain":{"vi":"一点儿也不: hoàn toàn không.","en":"一点儿也不: not at all."}},{"q":"下面哪个句子是正确的？","options":["这双鞋一点儿小，有大有点儿的吗？","这双鞋有点儿小，有大一点儿的吗？","这双鞋小有点儿，有一点儿大的吗？","这双鞋有点儿小，有有点儿大的吗？"],"answer":1,"explain":{"vi":"有点儿 + tính từ; tính từ + 一点儿.","en":"有点儿 + adjective; adjective + 一点儿."}},{"q":"我想喝____水。","options":["有点儿","一遍","一趟","一点儿"],"answer":3,"explain":{"vi":"Động từ + 一点儿 + danh từ: một ít.","en":"Verb + 一点儿 + noun: a little."}}]},
  {"id":"g69","title":{"zh":"往往 / 常常","vi":"往往 (thường thì) / 常常 (thường xuyên)","en":"往往 / 常常 (tends to / often)"},"pattern":"condition + S + 往往 + V (a regular tendency so far) | S + 常常 + V (frequency; past, present or future)","explain":{"vi":"常常 chỉ nói hành động xảy ra nhiều lần, dùng được cho cả tương lai và mong muốn. 往往 tổng kết quy luật từ kinh nghiệm đã có, cần nêu điều kiện hay hoàn cảnh, không dùng cho tương lai hay mong muốn. Lỗi hay gặp: 希望你往往来 (phải là 常常来).","en":"常常 simply says an action is frequent and works for the future and for wishes. 往往 sums up a regular pattern from experience, needs a stated condition or setting, and cannot be used for the future or wishes. Common mistake: 希望你往往来 (say 常常来)."},"examples":[{"zh":"压力大的时候，人往往容易生气。","py":"Yālì dà de shíhou, rén wǎngwǎng róngyì shēngqì.","vi":"Khi áp lực lớn, người ta thường dễ nổi giận.","en":"When under a lot of pressure, people tend to get angry easily."},{"zh":"欢迎你以后常常来我们公司。","py":"Huānyíng nǐ yǐhòu chángcháng lái wǒmen gōngsī.","vi":"Hoan nghênh bạn sau này thường xuyên đến công ty chúng tôi.","en":"You are welcome to visit our company often in future."}],"quiz":[{"q":"希望你以后____给我们提意见。","options":["往往","曾经","刚才","常常"],"answer":3,"explain":{"vi":"Mong muốn về tương lai chỉ dùng 常常.","en":"A wish about the future takes only 常常."}},{"q":"下面哪个句子是正确的？","options":["明天我往往去看你。","请你往往来玩儿。","周末他往往一个人去爬山。","我希望往往见到你。"],"answer":2,"explain":{"vi":"往往 nói quy luật trong hoàn cảnh nhất định (周末), không dùng cho tương lai hay mong muốn.","en":"往往 states a pattern in a given setting (周末) and is not used for the future or wishes."}},{"q":"“往往”不能用在下面哪种句子里？","options":["表示将来打算的句子","说明过去经验的句子","说明一般情况的句子","有条件的句子"],"answer":0,"explain":{"vi":"往往 không dùng cho việc trong tương lai.","en":"往往 is not used for future events."}},{"q":"刚开始工作的人，____缺少经验。","options":["曾经","往往","刚才","千万"],"answer":1,"explain":{"vi":"Tổng kết một quy luật chung dùng 往往.","en":"Summing up a general tendency takes 往往."}},{"q":"我以后一定____回来看您。","options":["常常","往往","从来","曾经"],"answer":0,"explain":{"vi":"Lời hứa về tương lai dùng 常常.","en":"A promise about the future takes 常常."}}]},
  {"id":"g70","title":{"zh":"好像 / 像……一样","vi":"好像 (hình như) / 像…一样 (giống như)","en":"好像 / 像…一样 (seem / be like)"},"pattern":"S + 好像 + clause (seems, not sure) | A + 像 + B + 一样 (+ Adj / V) | A + 不像 + B + 那么 + Adj","explain":{"vi":"好像: phỏng đoán chưa chắc chắn, \"hình như\". 像…一样: so sánh giống nhau, tính từ đứng sau 一样. Phủ định: 不像…那么…. Lỗi hay gặp: đặt tính từ trước 一样 theo trật tự tiếng Việt (像北京冷一样 là sai, phải nói 像北京一样冷).","en":"好像: an uncertain impression, \"it seems\". 像…一样: a comparison of likeness, with the adjective after 一样. Negative: 不像…那么…. Common mistake: putting the adjective before 一样 (像北京冷一样 is wrong; say 像北京一样冷)."},"examples":[{"zh":"他好像不太同意我们的计划。","py":"Tā hǎoxiàng bú tài tóngyì wǒmen de jìhuà.","vi":"Hình như anh ấy không đồng ý lắm với kế hoạch của chúng ta.","en":"He doesn't seem to agree much with our plan."},{"zh":"同事们像家人一样互相照顾。","py":"Tóngshìmen xiàng jiārén yíyàng hùxiāng zhàogù.","vi":"Các đồng nghiệp chăm sóc lẫn nhau như người một nhà.","en":"The colleagues look after each other like family."}],"quiz":[{"q":"天阴了，____要下雨了。","options":["尤其","一样","比如","好像"],"answer":3,"explain":{"vi":"Phỏng đoán chưa chắc chắn dùng 好像.","en":"An uncertain guess takes 好像."}},{"q":"她的汉语说得像中国人____好。","options":["一样","好像","比较","一起"],"answer":0,"explain":{"vi":"像…一样 + tính từ.","en":"像…一样 + adjective."}},{"q":"下面哪个句子是正确的？","options":["这里的冬天一样像北京冷。","这里的冬天像一样北京冷。","这里的冬天像北京一样冷。","这里的冬天冷像北京一样的。"],"answer":2,"explain":{"vi":"Trật tự: A + 像 + B + 一样 + tính từ.","en":"Order: A + 像 + B + 一样 + adjective."}},{"q":"我____在哪儿见过这个人，可是想不起来了。","options":["一样","好像","比如","尤其"],"answer":1,"explain":{"vi":"Cảm giác không chắc chắn: 好像.","en":"An unsure impression: 好像."}},{"q":"弟弟不像哥哥____爱说话。","options":["那么","多么","什么","怎么"],"answer":0,"explain":{"vi":"Phủ định: 不像…那么….","en":"Negative: 不像…那么…."}}]}
];
